sparql_query:
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?timeValue ?detailProp ?detailVal
WHERE {
  ?hazard rdf:type ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?timeNode . 
    ?timeNode time:inXSDDateTime ?timeValue . 
  }

  # Retrieve available details (properties and values)
  # Filter out rdf:type to avoid redundancy with the 'type' variable selected above
  OPTIONAL { 
    ?hazard ?detailProp ?detailVal . 
    FILTER ( ?detailProp != rdf:type )
  }
}
ORDER BY ?type ?timeValue ?hazard

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?attribute ?placeLabel ?attributeLabel
WHERE {
  ?place a kwg-ont:USCensusMSA .
  OPTIONAL { ?place rdfs:label ?placeLabel }
  ?collection sosa:hasFeatureOfInterest ?place .
  ?collection sosa:hasMember ?observation .
  ?observation sosa:observedProperty ?attribute .
  ?attribute rdfs:subClassOf* kwg-ont:CensusObservableProperty .
  OPTIONAL { ?attribute rdfs:label ?attributeLabel }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquake ?totalCount
WHERE {
  ?earthquake rdf:type kwg-ont:Earthquake .
  {
    SELECT (COUNT(DISTINCT ?e) AS ?totalCount)
    WHERE {
      ?e rdf:type kwg-ont:Earthquake .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?tornado ?place ?geometry ?totalCount
WHERE {
  ?tornado a kwg-ont:NOAATornado .

  # Retrieve attributes related to geographical places (Geometry and Spatial Relation)
  OPTIONAL { ?tornado geo:hasGeometry ?geometry }
  ?tornado kwg-ont:spatialRelation ?place .

  # Subquery to calculate total count of distinct tornadoes with spatial relations
  {
    SELECT (COUNT(DISTINCT ?sub_t) AS ?totalCount)
    WHERE {
      ?sub_t a kwg-ont:NOAATornado .
      ?sub_t kwg-ont:spatialRelation ?p_sub .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?place ?attribute ?value
WHERE {
  # Identify storm-related hazards (instances of NOAAHazardEvent or its subclasses)
  ?hazard rdf:type/rdfs:subClassOf* kwg-ont:NOAAHazardEvent .

  # Link to geographical places via geometry or spatial relations (e.g., Administrative Regions)
  {
    ?hazard geo:hasGeometry ?place .
  } UNION {
    ?hazard kwg-ont:spatialRelation ?place .
    ?place rdf:type/rdfs:subClassOf* kwg-ont:AdministrativeRegion .
  } UNION {
    # Include other features acting as geographical places if linked directly via geometry properties on the hazard itself (often treated as place info)
    ?hazard geo:hasDefaultGeometry ?geomPlace .
    BIND(?geomPlace AS ?place)
  }

  # Retrieve all available attributes and their details for the hazard
  OPTIONAL { ?hazard ?attribute ?value . }

  FILTER(BOUND(?attribute))
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?floodType ?property ?value ?geometry ?place
WHERE {
  # Identify flood hazard types (instances or classes representing floods)
  ?floodType rdfs:subClassOf* kwg-ont:NOAAFlood .

  # Retrieve general attributes/properties associated with the flood type
  OPTIONAL { ?floodType ?property ?value }

  # Retrieve geometry details (Geographical Place relation via Geometry)
  OPTIONAL { 
    ?floodType geo:hasGeometry ?geometry .
    ?geometry a geo:Geometry .
  }

  # Retrieve spatial relations to specific geographical places (e.g., AdministrativeRegions, Cells)
  OPTIONAL { 
    ?floodType kwg-ont:spatialRelation ?place .
    ?place a/rdfs:subClassOf* geo:Feature .
  }
}
ORDER BY ?floodType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?name ?startDate ?endDate ?hazardType ?affectedArea ?damageCrops ?damageInfrastructure ?deaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?place ?diabeticPercent ?obesePercent ?povertyLine ?population
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticPercent }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesePercent }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardType ?label ?totalCount
WHERE {
  {
    SELECT (COUNT(*) AS ?totalCount)
    WHERE {
      ?h a kwgl-ont:HazardType .
    }
  }
  ?hazardType a kwgl-ont:HazardType .
  OPTIONAL { ?hazardType rdfs:label ?label }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?predicate ?value
WHERE {
  ?place a kwgl-ont:Place .
  ?place ?predicate ?value .

  FILTER(
    CONTAINS(STR(?predicate), "dollarDamageOfTornadoesImpactingPlace") ||
    CONTAINS(STR(?predicate), "numberOfTornadoesImpactingPlace")
  )
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeName 
       ?hurricaneDamage ?hurricaneCount 
       ?stormSurgeDamage ?stormSurgeCount 
       ?tornadoDamage ?tornadoCount
WHERE {
  ?place a kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Hurricane Attributes
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }

  # Storm Surge Attributes
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?stormSurgeCount }

  # Tornado Attributes (often associated with storms)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?tornadoCount }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeName 
       ?totalFloodDamage ?floodDamage2018 ?floodDamage2019 ?floodDamage2020 ?floodDamage2021 ?floodDamage2022
       ?totalFloodCount ?floodCount2018 ?floodCount2019 ?floodCount2020 ?floodCount2021 ?floodCount2022
WHERE {
  ?place a kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Flood Damage Attributes (Total and Yearly)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?totalFloodDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?floodDamage2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?floodDamage2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?floodDamage2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?floodDamage2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?floodDamage2022 }

  # Flood Count Attributes (Total and Yearly)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?totalFloodCount }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?floodCount2018 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?floodCount2019 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?floodCount2020 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?floodCount2021 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?floodCount2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?name 
       ?avgCoolingDegreeDays ?avgHeatingDegreeDays 
       ?avgMonthlyTemp ?maxMonthlyTemp ?minMonthlyTemp
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?avgCoolingDegreeDays }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?avgHeatingDegreeDays }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?avgMonthlyTemp }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?maxMonthlyTemp }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?minMonthlyTemp }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?name ?startDate ?endDate ?area ?cropDamage ?infraDamage ?deaths ?hazardType ?typeLabel
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { 
    ?earthquake kwgl-ont:hasHazardType ?hazardType .
    OPTIONAL { ?hazardType rdfs:label ?typeLabel }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?name ?hazardType ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?place ?damageToCropsInDollars ?damageToInfrastructureInDollars ?affectedAreaInAcres ?numberOfDeaths 
       ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace ?dollarDamageOfHurricanesImpactingPlace
       ?dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace
WHERE {
  # Find HazardEvents with damage details
  OPTIONAL {
    ?hazardEvent a kwgl-ont:HazardEvent .
    OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
    OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
    OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
  }

  # Find Places impacted by hazards with damage details
  OPTIONAL {
    ?place a kwgl-ont:Place .
    ?place kwgl-ont:impactedBy ?hazardEvent .
    OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace }
  }

  # Ensure at least one damage detail exists
  FILTER(BOUND(?damageToCropsInDollars) || BOUND(?damageToInfrastructureInDollars) || 
         BOUND(?affectedAreaInAcres) || BOUND(?numberOfDeaths) ||
         BOUND(?dollarDamageOfFiresImpactingPlace) || BOUND(?dollarDamageOfFloodsImpactingPlace) ||
         BOUND(?dollarDamageOfHurricanesImpactingPlace) || BOUND(?dollarDamageOfLandslidesImpactingPlace) ||
         BOUND(?dollarDamageOfStormSurgesImpactingPlace) || BOUND(?dollarDamageOfTornadoesImpactingPlace))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?placeName ?hurricaneCount ?dollarDamage ?eventStart ?eventEnd ?affectedArea ?damageCrops ?damageInfra ?deaths
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Hurricane-specific attributes on Place (Aggregated)
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamage }

  # Link to specific Hurricane Events for detailed temporal and damage data
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?event .
    ?event a kwgl-ont:Hurricane .

    # Temporal Data
    OPTIONAL { ?event kwgl-ont:hasStartDate ?eventStart }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?eventEnd }

    # Damage Impact Details on Event
    OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops }
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
    OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?startDate ?endDate ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?affectedAreaInAcres
WHERE {
  ?hazard a kwgl-ont:Tornado .
  ?hazard kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .
  ?hazard kwgl-ont:hasStartDate ?startDate .
  ?hazard kwgl-ont:hasEndDate ?endDate .
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?event ?placeName ?damageCrops ?damageInfrastructure ?startDate ?endDate ?hazardTypeLabel
WHERE {
  # Identify storm-specific hazard events (Hurricane, Tornado classes or specific HazardTypes)
  { 
    ?event a kwgl-ont:Hurricane .
  }
  UNION
  { 
    ?event a kwgl-ont:Tornado .
  }
  UNION
  { 
    ?event kwgl-ont:hasHazardType ?ht .
    VALUES ?ht { 
      kwglr:hurricane 
      kwglr:tropicalStorm 
      kwglr:tropicalDepression 
      kwglr:winterStorm 
      kwglr:stormSurgeTide 
    }
  }

  # Link to impacted geographical place
  ?event kwgl-ont:hasImpacted ?place .

  # Retrieve Place Name for context
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Retrieve Temporal Extent (Start and End Dates)
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  # Retrieve Damage Details available on the HazardEvent
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }

  # Retrieve Hazard Type Label for identification
  OPTIONAL { ?ht rdfs:label ?hazardTypeLabel }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?agent ?department
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?univ ?state ?count
WHERE {
  {
    SELECT ?univ ?state (COUNT(?pub) AS ?count)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author a coress-ont:Author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?univ .
      ?univ a coress-ont:University .
      ?univ coress-ont:atState ?state .
    }
    GROUP BY ?univ ?state
  }
  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?univ ?state (COUNT(?pub) AS ?c)
        WHERE {
          ?pub a coress-ont:Publication .
          ?pub coress-ont:submittedBy ?author .
          ?author a coress-ont:Author .
          ?author coress-ont:isPerformedBy ?agent .
          ?agent coress-ont:worksInDepartment ?dept .
          ?dept coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?univ .
          ?univ a coress-ont:University .
          ?univ coress-ont:atState ?state .
        }
        GROUP BY ?univ ?state
      }
    }
    GROUP BY ?state
  }
  FILTER (?count = ?maxCount)
}
ORDER BY ?state DESC(?count)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?type ?startDate ?endDate ?area ?deaths ?damageInfra ?damageCrops ?entity
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:hasKWGEntity ?entity }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?name ?totalCount WHERE {
    ?hazard rdf:type kwgl-ont:HazardEvent .
    ?hazard kwgl-ont:hasHazardType kwglr:earthquake .
    OPTIONAL { ?hazard kwgl-ont:hasName ?name }

    {
        SELECT (COUNT(*) AS ?totalCount) WHERE {
            ?s rdf:type kwgl-ont:HazardEvent ;
               kwgl-ont:hasHazardType kwglr:earthquake .
        }
    }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (COUNT(?attr) AS ?totalCount)
WHERE {
  {
    SELECT ?attr WHERE {
      ?attr rdf:type owl:DatatypeProperty .
      FILTER(CONTAINS(LCASE(STR(?attr)), "tornado"))
    }
  }
  ?attribute = ?attr.
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "storm") ||
    CONTAINS(LCASE(STR(?attribute)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?subPropertyOf ?subPropertyLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:range ?range }
  OPTIONAL { ?attribute rdfs:label ?label }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?subPropertyOf .
    OPTIONAL { ?subPropertyOf rdfs:label ?subPropertyLabel }
  }

  FILTER ( CONTAINS(LCASE(STR(?attribute)), "flood") )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?label . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  # Check for domain association with Place if available in schema data, otherwise rely on naming convention
  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }

  FILTER (
    LCASE(STR(?attribute)) CONTAINS "temperature" ||
    LCASE(STR(?attribute)) CONTAINS "cooling" ||
    LCASE(STR(?attribute)) CONTAINS "heating"
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?affectedArea ?numberOfDeaths ?damageInfrastructure ?hazardType
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }

  OPTIONAL { 
    ?hazard kwgl-ont:hasHazardType ?hazardType .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?name ?hazardType ?deaths ?area ?damageCrops ?damageInfrastructure
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?area . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?placeName ?hazardType ?fireDamage ?floodDamage ?hurricaneDamage ?tornadoDamage ?landslideDamage ?stormSurgeDamage
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  ?place kwgl-ont:impactedBy ?hazard .
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?fireDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?landslideDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?place ?startDate ?endDate ?tornadoDamageDollar ?numberOfTornadoes ?infraDamage ?cropsDamage ?deaths
WHERE {
  ?hazard rdf:type kwgl-ont:Tornado .
  ?hazard kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamageDollar . }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?numberOfTornadoes . }

  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropsDamage . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?name ?timeScope ?geometry ?description WHERE {
  { ?hazard a kwg-ont:Hazard } UNION
  { ?hazard a kwg-ont:FEMADisaster } UNION
  { ?hazard a kwg-ont:DroughtZone } UNION
  { ?hazard a kwg-ont:Earthquake } UNION
  { ?hazard a kwg-ont:NOAAHazardEvent } UNION
  { ?hazard a kwg-ont:Fire } UNION
  { ?hazard a kwg-ont:SmokePlumeSnapshot } UNION
  { ?hazard a kwg-ont:MTBSFire } UNION
  { ?hazard a kwg-ont:NIFCFire }

  # Retrieve Name Details (Generic Label or Specific Names)
  OPTIONAL { ?hazard rdfs:label ?label . }
  OPTIONAL { ?hazard kwg-ont:hasDisasterName ?disasterName . }
  OPTIONAL { ?hazard kwg-ont:hasFireName ?fireName . }
  OPTIONAL { ?hazard kwg-ont:hasIncidentName ?incidentName . }
  BIND(COALESCE(?disasterName, ?fireName, ?incidentName, ?label) AS ?name)

  # Retrieve Time (When it happened)
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?timeScope . }

  # Retrieve Geometry Details
  OPTIONAL { ?hazard geo:hasGeometry ?geometry . }

  # Retrieve Narrative/Description Details
  OPTIONAL { ?hazard kwg-ont:hasNarrative ?description . }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?healthConcern ?concernLabel
WHERE {
  ?observation a sosa:Observation .
  ?observation sosa:hasFeatureOfInterest ?place .
  ?place a geo:Feature .
  ?observation sosa:observedProperty ?healthConcern .

  FILTER (
    EXISTS { ?healthConcern rdfs:subClassOf+ kwg-ont:PublicHealthObservableProperty } ||
    EXISTS { ?healthConcern rdfs:subClassOf+ kwg-ont:VulnerabilityObservableProperty } ||
    EXISTS { ?healthConcern rdfs:subClassOf+ kwg-ont:CensusObservableProperty } || 
    EXISTS { ?healthConcern rdfs:subClassOf+ kwg-ont:DroughtIntensity }
  ) .

  OPTIONAL { ?place rdfs:label ?placeLabel }
  OPTIONAL { ?healthConcern rdfs:label ?concernLabel }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?earthquake (COUNT(*) AS ?totalCount) WHERE {
  ?earthquake a kwg-ont:Earthquake .
  {
    SELECT (COUNT(*) AS ?count) WHERE {
      ?e a kwg-ont:Earthquake .
    }
  }
  BIND(?count AS ?totalCount)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardLabel ?attrName ?placeName ?locationType
WHERE {
  # Identify Storm-related Hazards (NOAA Hazard Events or Storm Tracks)
  { ?hazard rdf:type kwg-ont:NOAAHazardEvent . }
  UNION
  { ?hazard rdf:type kwg-ont:StormTrack . }

  # Retrieve Hazard Name/Details
  OPTIONAL { 
    ?hazard rdfs:label ?hazardLabel . 
  }
  OPTIONAL {
    ?hazard kwg-ont:hasDisasterName ?disasterName .
    BIND(COALESCE(?disasterName, ?hazardLabel) AS ?hazardLabel)
  }

  # Retrieve Storm-Specific Attributes via Observations
  OPTIONAL {
    ?obs sosa:hasFeatureOfInterest ?hazard .
    ?obs sosa:observedProperty ?attr .

    # Optional: Filter for storm-specific observable properties if typed explicitly in data
    # ?attr rdf:type kwg-ont:StormTrackObservableProperty . 
  }

  OPTIONAL { ?attr rdfs:label ?attrName . }

  # Retrieve Associated Geographical Places
  OPTIONAL {
    { ?hazard kwg-ont:sfWithin ?place . }
    UNION
    { ?hazard kwg-ont:spatialRelation ?place . }

    OPTIONAL { 
      ?place rdfs:label ?placeName . 
    }
    OPTIONAL {
      ?place rdf:type ?locationType .
    }
  }

  # Also include Geometry as a place detail if available
  OPTIONAL {
     ?hazard geo:hasDefaultGeometry ?geom .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?flood ?type ?label ?geometry ?defaultGeometry ?place ?relationType ?temporalScope
WHERE {
  VALUES ?type { 
    kwg-ont:NOAACoastalFlood 
    kwg-ont:NOAAFlashFlood 
    kwg-ont:NOAALakeshoreFlood 
    kwg-ont:NOAAFlood 
  }

  ?flood a ?type .

  OPTIONAL { ?flood rdfs:label ?label . }
  OPTIONAL { ?flood geo:hasGeometry ?geometry . }
  OPTIONAL { ?flood geo:hasDefaultGeometry ?defaultGeometry . }
  OPTIONAL { ?flood kwg-ont:spatialRelation ?place . BIND("spatialRelation" AS ?relationType) }
  OPTIONAL { ?flood kwg-ont:sfWithin ?place . BIND("sfWithin" AS ?relationType) }
  OPTIONAL { ?flood kwg-ont:sfContains ?place . BIND("sfContains" AS ?relationType) }
  OPTIONAL { ?flood kwg-ont:hasTemporalScope ?temporalScope . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?earthquake ?type ?geometry ?temporalScope
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  ?earthquake a ?type .
  OPTIONAL { ?earthquake geo:hasDefaultGeometry ?geometry }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?superType ?property ?value ?timeScope
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:subClassOf ?superType . }
  OPTIONAL { ?hazard ?property ?value . }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?timeScope . }
}
ORDER BY ?hazard ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?placeName ?propertyLabel
WHERE {
  {
    # Public Health Observations via Collection linked to Administrative Regions
    ?collection a kwg-ont:PublicHealthObservationCollection .
    ?collection sosa:hasFeatureOfInterest ?place .
    ?collection sosa:hasMember ?obs .
    ?obs sosa:observedProperty ?property .
  } UNION {
    # Vulnerability Observations directly linked to Administrative Regions
    ?obs a kwg-ont:VulnerabilityObservation .
    ?obs sosa:hasFeatureOfInterest ?place .
    ?obs sosa:observedProperty ?property .
  }

  # Ensure the place is an Administrative Region (Geographical Place) or subclass
  ?place a kwg-ont:AdministrativeRegion .

  OPTIONAL { ?place rdfs:label ?placeName . }
  OPTIONAL { ?property rdfs:label ?propertyLabel . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?allAttributes) AS ?totalCount)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?allAttributes)
    WHERE {
      ?attr rdfs:subClassOf sosa:ObservableProperty .
      FILTER(CONTAINS(STR(?attr), "fujita") || CONTAINS(STR(?attr), "tornado"))
    }
  }
  ?attribute rdfs:subClassOf sosa:ObservableProperty .
  FILTER(CONTAINS(STR(?attribute), "fujita") || CONTAINS(STR(?attribute), "tornado"))
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?floodType ?property ?value ?place
WHERE {
  VALUES ?rootFloodClass { kwg-ont:NOAAFlood kwg-ont:NOAAFlashFlood kwg-ont:NOAACoastalFlood kwg-ont:NOAALakeshoreFlood }
  ?floodType rdfs:subClassOf* ?rootFloodClass .

  OPTIONAL { ?floodType ?property ?value . }

  OPTIONAL { 
    ?floodType rdfs:subClassOf+ ?superClass .
    ?superClass kwg-ont:spatialRelation ?place .
  }
}
ORDER BY ?floodType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?earthquakeType ?superType ?label ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType }
  OPTIONAL { ?earthquakeType rdfs:label ?label }
  OPTIONAL { ?earthquakeType ?property ?value }
}
ORDER BY ?earthquakeType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hurricane ?hazardAttr ?attrVal ?geom ?place ?timeScope ?impact ?damageProp ?impactResult ?impTime
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  # Retrieve all available attributes for the hurricane hazard instance
  OPTIONAL { ?hurricane ?hazardAttr ?attrVal }

  # Geographical place relations (Geometry and Spatial Relation)
  OPTIONAL { ?hurricane geo:hasGeometry ?geom }
  OPTIONAL { ?hurricane kwg-ont:spatialRelation ?place }

  # Temporal data for the hazard
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?timeScope }

  # Damage impact details linked to the hurricane
  OPTIONAL { 
    ?impact sosa:observedProperty ?damageProp .
    ?impact sosa:hasFeatureOfInterest ?hurricane .
    OPTIONAL { ?impact sosa:hasSimpleResult ?impactResult }
    OPTIONAL { ?impact sosa:phenomenonTime ?impTime }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?hazard ?label ?timeVal ?geometry
WHERE {
    ?hazard rdf:type kwg-ont:Hazard .

    OPTIONAL { ?hazard rdfs:label ?label }
    OPTIONAL { ?hazard geo:asWKT ?geometry }

    OPTIONAL { 
        ?hazard kwg-ont:hasTemporalScope ?tempEntity .
        { ?tempEntity time:inXSDDate ?timeVal }
        UNION
        { ?tempEntity time:inXSDDateTime ?timeVal }
        UNION
        { ?tempEntity time:inXSDgYear ?timeVal }
    }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?label ?totalCount WHERE {
  ?earthquake rdf:type kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
  {
    SELECT (COUNT(*) AS ?totalCount) WHERE {
      ?e rdf:type kwg-ont:Earthquake .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?attributeLabel ?totalCount
WHERE {
  OPTIONAL { 
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount) WHERE { 
      ?attr rdf:type kwg-ont:MagnitudeObservableProperty . 
    }
  }
  ?attr rdf:type kwg-ont:MagnitudeObservableProperty .
  OPTIONAL { ?attr rdfs:label ?attributeLabel }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardEvent ?typeLabel ?narrative ?obsProperty ?resultValue ?placeUri ?placeTypeLabel ?geometryWKT
WHERE {
  ?hazardEvent a kwg-ont:NOAAHazardEvent .

  OPTIONAL {
    ?hazardEvent rdf:type ?typeClass .
    FILTER(?typeClass != kwg-ont:NOAAHazardEvent) 
    ?typeClass rdfs:label ?typeLabel .
  }

  OPTIONAL {
    ?episode kwg-ont:episodeHasPart ?hazardEvent .
    ?episode kwg-ont:hasNarrative ?narrative .
  }

  OPTIONAL {
    ?obs sosa:isFeatureOfInterestOf ?hazardEvent .
    ?obs sosa:observedProperty ?obsProperty .
    OPTIONAL { ?obs sosa:hasResult ?resultValue . }
  }

  OPTIONAL {
    ?hazardEvent kwg-ont:sfWithin ?placeUri .
    OPTIONAL { 
      ?placeUri rdf:type ?placeTypeClass . 
      ?placeTypeClass rdfs:label ?placeTypeLabel . 
    }
  }

  OPTIONAL { ?hazardEvent geo:asWKT ?geometryWKT . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazard ?floodTypeLabel ?placeName ?observedPropertyLabel ?wktGeometry
WHERE {
  # Identify specific flood hazard event classes defined in the schema
  VALUES ?floodClass { 
    kwg-ont:NOAACoastalFlood 
    kwg-ont:NOAALakeshoreFlood 
    kwg-ont:NOAAFlashFlood 
    kwg-ont:NOAAFlood 
  }

  # Match hazard instances to flood classes
  ?hazard rdf:type ?floodClass .

  # Retrieve the type label as an attribute detail
  ?floodClass rdfs:label ?floodTypeLabel .

  # Retrieve related geographical places via spatial relations defined in schema
  OPTIONAL {
    ?hazard kwg-ont:spatialRelation ?place .
    ?place a geo:Feature .
    OPTIONAL { ?place rdfs:label ?placeName }
  }

  # Retrieve hazard attributes and details through SOSA observations linked to the event
  OPTIONAL {
    ?hazard sosa:isFeatureOfInterestOf ?observation .
    ?observation sosa:observedProperty ?attr .
    ?attr rdfs:label ?observedPropertyLabel .
  }

  # Retrieve geometry details for spatial representation of the hazard
  OPTIONAL {
    ?hazard geo:hasGeometry ?geom .
    ?geom geo:asWKT ?wktGeometry .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute ?label
WHERE {
    ?attribute a kwg-ont:ClimateObservableProperty .
    OPTIONAL { ?attribute rdfs:label ?label }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?earthquake ?label ?typeLabel ?geometry ?timeInstant ?detailLabel
WHERE {
  ?earthquake a kwg-ont:Earthquake .

  # Retrieve Earthquake Name/Details (Label)
  OPTIONAL { 
    ?earthquake rdfs:label ?label .
  }
  OPTIONAL {
    ?earthquake skos:prefLabel ?label .
  }

  # Retrieve Types (rdf:type hierarchy)
  OPTIONAL { 
    ?earthquake rdf:type ?type .
    ?type rdfs:label ?typeLabel .
  }

  # Retrieve Geometry Details
  OPTIONAL { 
    ?earthquake geo:hasDefaultGeometry ?geometry .
  }

  # Retrieve Temporal Scope Details (Time)
  OPTIONAL { 
    ?earthquake kwg-ont:hasTemporalScope ?timeEntity .
    ?timeEntity time:inXSDDateTime ?timeInstant .
  }

  # Retrieve Associated Observations for Hazard Details (e.g. Magnitude, Depth, Type of Earthquake Data)
  OPTIONAL { 
    ?obs sosa:isFeatureOfInterestOf ?earthquake .
    ?obs sosa:observedProperty ?prop .
    ?prop rdfs:label ?detailLabel .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?amountApprovedHA ?amountApprovedIHP ?obligatedAmountPA
WHERE {
  ?hazard rdf:type kwg-ont:Hazard .

  OPTIONAL { ?hazard kwg-ont:amountApproved_HA ?amountApprovedHA }
  OPTIONAL { ?hazard kwg-ont:amountApproved_IHP ?amountApprovedIHP }
  OPTIONAL { ?hazard kwg-ont:obligatedAmount_PA ?obligatedAmountPA }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?placeLabel ?damageAttribute ?timeValue
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  # Geographical Place relation (Optional)
  OPTIONAL { 
    ?hurricane kwg-ont:sfWithin ?place .
    ?place rdfs:label ?placeLabel .
  }

  # Damage Impact Details via ImpactObservation
  OPTIONAL {
    ?impactObs sosa:hasFeatureOfInterest ?hurricane .
    ?impactObs sosa:observedProperty ?damageAttribute .
  }

  # Temporal Data from Observation or Event Scope
  OPTIONAL { 
    ?impactObs time:inXSDDateTime ?t1 . 
  }
  OPTIONAL { 
    ?hurricane kwg-ont:hasTemporalScope ?tempEntity . 
    ?tempEntity time:inXSDDateTime ?t2 . 
  }

  BIND (COALESCE(?t1, ?t2) AS ?timeValue)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?stormEvent ?damageProperty ?damageCrop ?deathDirect ?deathIndirect ?injuryDirect ?injuryIndirect ?geographicalPlace ?temporalExtent ?beginTime ?endTime
WHERE {
  # Storm-specific hazards (NOAA Hazard Events)
  ?stormEvent a kwg-ont:NOAAHazardEvent .

  # Get impact/damage observations related to the storm event
  ?impactObs sosa:hasFeatureOfInterest ?stormEvent .
  ?impactObs a kwg-ont:ImpactObservation .

  # Retrieve damage details (damage property, crop, deaths, injuries)
  OPTIONAL { ?impactObs sosa:observedProperty ?damageProperty . }
  OPTIONAL { ?impactObs sosa:observedProperty ?damageCrop . }
  OPTIONAL { ?impactObs sosa:observedProperty ?deathDirect . }
  OPTIONAL { ?impactObs sosa:observedProperty ?deathIndirect . }
  OPTIONAL { ?impactObs sosa:observedProperty ?injuryDirect . }
  OPTIONAL { ?impactObs sosa:observedProperty ?injuryIndirect . }

  # Get spatial relationship with geographical places
  ?stormEvent kwg-ont:sfWithin|kwg-ont:sfContains|kwg-ont:spatialRelation ?geographicalPlace .
  ?geographicalPlace a geo:Feature .

  # Get temporal extent information
  ?stormEvent kwg-ont:hasTemporalScope ?temporalExtent .
  OPTIONAL { ?temporalExtent time:hasBeginning ?beginTime . }
  OPTIONAL { ?temporalExtent time:hasEnd ?endTime . }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?author ?firstName ?lastName
WHERE {
  ?author rdf:type coress-ont:Author .
  OPTIONAL { ?author coress-ont:hasFirstName ?firstName }
  OPTIONAL { ?author coress-ont:hasFamilyName ?lastName }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?university ?count WHERE {
  {
    SELECT ?state ?university (COUNT(DISTINCT ?pub) AS ?count)
    WHERE {
      ?pub coress-ont:submittedBy ?author .
      ?agent coress-ont:performsRole ?author .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?cnt) AS ?maxCount)
    WHERE {
      SELECT ?state ?uni (COUNT(DISTINCT ?p) AS ?cnt)
      WHERE {
        ?p coress-ont:submittedBy ?auth .
        ?ag coress-ont:performsRole ?auth .
        ?ag coress-ont:worksInDepartment ?dpt .
        ?dpt coress-ont:departmentOf ?col .
        ?col coress-ont:collegeOf ?uni .
        ?uni coress-ont:atState ?st .
      }
      GROUP BY ?state ?uni
    }
    GROUP BY ?state
  }
  FILTER (?count = ?maxCount)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publicationType
WHERE {
  {
    SELECT ?publicationType (AVG(?timeDiff) AS ?avgTime)
    WHERE {
      ?pub a coress-ont:Publication ;
           coress-ont:hasPublicationType ?publicationType ;
           coress-ont:dateOfSubmission ?subDate ;
           coress-ont:dateOfPublication ?pubDate .
      BIND ((?pubDate - ?subDate) AS ?timeDiff)
    }
    GROUP BY ?publicationType
    ORDER BY DESC(?avgTime)
    LIMIT 1
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazard
  ?name
  ?startDate
  ?endDate
  ?area
  ?deaths
  ?infraDamage
  ?cropsDamage
  ?hazardType
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropsDamage }

  OPTIONAL { 
    ?hazard kwgl-ont:hasHazardType ?hazardType .
  }
}
ORDER BY ?startDate DESC

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
}
ORDER BY ?name

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?population ?households ?povertyLine ?diabeticPercent ?obesePercent ?name WHERE {
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasPopulation ?population . }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households . }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine . }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticPercent . }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesePercent . }
  OPTIONAL { ?place kwgl-ont:hasName ?name . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard (COUNT(*) AS ?totalCount) WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard rdfs:label ?label }
  {
    SELECT (COUNT(*) AS ?countInner) WHERE { ?eq rdf:type kwgl-ont:Earthquake }
  }
  BIND(?countInner AS ?totalCount)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label (SAMPLE(?totalCount) AS ?totalAttributes)
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "tornado") || 
    CONTAINS(LCASE(STR(?label)), "tornado")
  )

  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }

  {
    SELECT (COUNT(*) AS ?totalCount) WHERE {
      ?p rdf:type owl:DatatypeProperty .
      FILTER (
        CONTAINS(LCASE(STR(?p)), "tornado") || 
        CONTAINS(LCASE(STR(?label2)), "tornado")
      )
      OPTIONAL { ?p rdfs:label ?label2 }
    }
  }
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
  ?domain
  ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:domain ?domain }
  OPTIONAL { ?attribute rdfs:range ?range }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "stormsurge")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:range ?range }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "temperature") ||
    CONTAINS(LCASE(STR(?attribute)), "degree") ||
    (BOUND(?label) && (CONTAINS(LCASE(STR(?label)), "temperature") || CONTAINS(LCASE(STR(?label)), "degree")))
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?earthquake ?name ?startDate ?endDate ?hazardType ?affectedAreaInAcres ?numberOfDeaths ?damageToInfrastructureInDollars ?damageToCropsInDollars
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?hazardName
  ?hazardType
  ?numberOfDeaths
  ?damageToInfrastructureInDollars
  ?damageToCropsInDollars
  ?affectedAreaInAcres
  ?startDate
  ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName . }

  OPTIONAL {
    ?hazardEvent kwgl-ont:hasHazardType ?hazardType .
  }

  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hazardType ?damageProperty ?damageValue
WHERE {
  ?place kwgl-ont:impactedBy ?hazard .
  OPTIONAL { ?hazard rdf:type ?hazardType }
  ?place ?damageProperty ?damageValue .
  FILTER(
    CONTAINS(LCASE(STR(?damageProperty)), "damage") || 
    CONTAINS(LCASE(STR(?damageProperty)), "dollars")
  )
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hurricaneAttribute ?value ?startDate ?endDate ?yearFromAttr
WHERE {
  # Identify geographical places
  ?place rdf:type kwgl-ont:Place .

  {
    # Retrieve hurricane-specific attributes related to the place (counts, damages)
    ?place ?hurricaneAttribute ?value .

    # Filter for properties specifically related to Hurricanes
    FILTER(CONTAINS(STR(?hurricaneAttribute), "Hurricane"))

    # Extract temporal year from property name if available (e.g. ...ImpactingPlace2021)
    OPTIONAL { 
      BIND(STRAFTER(STR(?hurricaneAttribute), "ImpactingPlace") AS ?yearFromAttr)
    }

    # Retrieve explicit temporal data from linked Hurricane events if available
    OPTIONAL {
      ?place kwgl-ont:impactedBy ?event .
      ?event rdf:type kwgl-ont:Hurricane .
      OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
      OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }
    }
  }
}
ORDER BY ?place ?hurricaneAttribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hazardType ?damageAmount ?startDate ?endDate
WHERE {
  ?place a kwgl-ont:Place .

  # Link to HazardEvent to retrieve temporal extent (Start/End dates)
  ?place kwgl-ont:impactedBy ?event .
  ?event kwgl-ont:hasStartDate ?startDate .
  ?event kwgl-ont:hasEndDate ?endDate .

  # Filter for storm-specific HazardEvents defined in schema (Hurricane, Tornado)
  ?event a ?hazardType .
  FILTER (?hazardType = kwgl-ont:Hurricane || ?hazardType = kwgl-ont:Tornado)

  # Retrieve damage details associated with the place from relevant properties
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage . }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?surgeCount . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?surgeDamage . }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?floodCount . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamage . }

  # Consolidate damage amounts into a single variable for readability (prioritizing dollar damage)
  BIND(COALESCE(?hurricaneDamage, ?tornadoDamage, ?surgeDamage, ?floodDamage, ?surgeCount, ?floodCount) AS ?damageAmount)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub
WHERE {
  {
    ?pub coresr-ont:submittedBy ?authorRole .
    ?authorRole coresr-ont:isPerformedBy ?agent .
  } UNION {
    ?pub coresr-ont:hasContributor ?contributorRole .
    ?contributorRole coresr-ont:isPerformedBy ?agent .
  }
  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?dept (COUNT(?agent) AS ?missingCount)
WHERE {
  ?dept a coresr-ont:Department .
  ?dept coresr-ont:hasAssociatedAgent ?agent .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?dept
ORDER BY DESC(?missingCount)
LIMIT 1

