PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute (COUNT(?totalAttr) AS ?totalCount)
WHERE {
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalAttr)
    WHERE {
      kwgl-ont:Place ?attr ?range .
      FILTER(CONTAINS(LCASE(STR(?attr)), "tornado"))
    }
  }
  kwgl-ont:Place ?attribute ?range .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL { 
    ?attribute rdfs:subPropertyOf ?parentAttribute . 
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . } 
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazardResource ?resourceType ?label ?parentClass
WHERE {
  {
    # Retrieve HazardType instances related to earthquake
    ?hazardResource rdf:type kwgl-ont:HazardType .
    OPTIONAL { ?hazardResource rdfs:label ?label }
    FILTER ( CONTAINS(LCASE(STR(?hazardResource)), "earthquake") )
  }
  UNION
  {
    # Retrieve Earthquake Class definition (subclass of HazardEvent)
    ?hazardResource rdf:type owl:Class .
    ?hazardResource rdfs:subClassOf kwgl-ont:HazardEvent .
    OPTIONAL { ?resourceLabel ?label }
    FILTER ( CONTAINS(LCASE(STR(?hazardResource)), "earthquake") )
  }
  # Optional details available in schema
  OPTIONAL { 
    ?hazardResource rdfs:subClassOf ?parentClass .
    OPTIONAL { ?parentClass rdfs:label ?parentLabel }
  }
  BIND ( STR( ?resourceType ) AS ?resourceType )
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?eventName ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?eventName }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?entity ?damageType ?value
WHERE {
  {
    # Query Places with specific impact damage properties
    ?entity rdf:type kwgl-ont:Place .
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfFiresImpactingPlace ?vFire . BIND("Dollar Damage of Fires Impacting Place" AS ?damageType) }
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfFloodsImpactingPlace ?vFlood . BIND("Dollar Damage of Floods Impacting Place" AS ?damageType) }
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?vHurricane . BIND("Dollar Damage of Hurricanes Impacting Place" AS ?damageType) }
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?vLandslide . BIND("Dollar Damage of Landslides Impacting Place" AS ?damageType) }
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?vStormSurge . BIND("Dollar Damage of Storm Surges Impacting Place" AS ?damageType) }
    OPTIONAL { ?entity kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?vTornado . BIND("Dollar Damage of Tornadoes Impacting Place" AS ?damageType) }
    VALUES (?value ?damageProperty) { 
      ( ?vFire ?kwgl-ont:dollarDamageOfFiresImpactingPlace )
      ( ?vFlood ?kwgl-ont:dollarDamageOfFloodsImpactingPlace )
      ( ?vHurricane ?kwgl-ont:dollarDamageOfHurricanesImpactingPlace )
      ( ?vLandslide ?kwgl-ont:dollarDamageOfLandslidesImpactingPlace )
      ( ?vStormSurge ?kwgl-ont:dollarDamageOfStormSurgesImpactingPlace )
      ( ?vTornado ?kwgl-ont:dollarDamageOfTornadoesImpactingPlace ) 
    }
  } UNION {
    # Query HazardEvents with general damage properties
    ?entity rdf:type kwgl-ont:HazardEvent .
    OPTIONAL { ?entity kwgl-ont:damageToCropsInDollars ?vCrops . BIND("Damage to Crops in Dollars" AS ?damageType) }
    OPTIONAL { ?entity kwgl-ont:damageToInfrastructureInDollars ?vInfra . BIND("Damage to Infrastructure in Dollars" AS ?damageType) }
    VALUES (?value ?damageProperty) { 
      ( ?vCrops ?kwgl-ont:damageToCropsInDollars )
      ( ?vInfra ?kwgl-ont:damageToInfrastructureInDollars ) 
    }
  }
  FILTER(BOUND(?value))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?label
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?label . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL { 
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") && 
    (CONTAINS(LCASE(STR(?attribute)), "impactingplace") || CONTAINS(LCASE(STR(?label)), "hurricane"))
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?hazardType ?placeName ?startDate ?endDate ?damageCrops ?damageInfrastructure ?deaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  ?event kwgl-ont:hasHazardType ?hazardType .
  ?event kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }

  FILTER (
    CONTAINS(LCASE(STR(?hazardType)), "storm") || 
    CONTAINS(LCASE(STR(?hazardType)), "tornado") || 
    CONTAINS(LCASE(STR(?hazardType)), "hurricane") || 
    CONTAINS(LCASE(STR(?hazardType)), "blizzard")
  )
}

