PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?attribute ?value
WHERE {
  ?place rdf:type kwgl-ont:Place .
  {
    ?place kwgl-ont:percentDiabetic ?value .
    BIND(kwgl-ont:percentDiabetic AS ?attribute)
  } UNION {
    ?place kwgl-ont:percentObese ?value .
    BIND(kwgl-ont:percentObese AS ?attribute)
  } UNION {
    ?place kwgl-ont:percentBelowPovertyLine ?value .
    BIND(kwgl-ont:percentBelowPovertyLine AS ?attribute)
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?hazard ?name (COUNT(*) AS ?totalCount)
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL {
    SELECT (COUNT(*) AS ?count) WHERE { ?x rdf:type kwgl-ont:Earthquake }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute (COUNT(*) AS ?totalCount)
WHERE {
  { SELECT DISTINCT ?attr WHERE { 
      ?attr rdf:type owl:DatatypeProperty . 
      FILTER(CONTAINS(LCASE(STR(?attr)), "tornado")) 
    } 
  }
  BIND(?attr AS ?attribute)
  { SELECT (COUNT(DISTINCT ?a) AS ?totalCount) WHERE { 
      ?a rdf:type owl:DatatypeProperty . 
      FILTER(CONTAINS(LCASE(STR(?a)), "tornado")) 
    } 
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:range ?range }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "temperature") || 
    CONTAINS(LCASE(STR(?attribute)), "degreedays")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT
  ?hazard
  ?name
  ?startDate
  ?endDate
  ?deaths
  ?damageInfrastructure
  ?damageCrops
  ?affectedArea
  ?type
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }

  OPTIONAL { 
    ?hazard kwgl-ont:hasHazardType ?type .
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?name ?hazardType ?startDate ?endDate ?deaths ?cropDamage ?infraDamage ?area
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:hasName ?name }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  # Impact Factor Details
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?area }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  ?hazard
  ?damageFires
  ?damageFloods
  ?damageHurricanes
  ?damageLandslides
  ?damageStormSurges
  ?damageTornadoes
  ?damageCrops
  ?damageInfrastructure
  ?affectedArea
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?place kwgl-ont:impactedBy ?hazard .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?damageFires . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageFloods . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageHurricanes . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?damageLandslides . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageStormSurges . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageTornadoes . }

  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?property ?label ?range ?temporalYear
WHERE {
  ?property rdf:type owl:DatatypeProperty .

  # Filter for hurricane-specific attributes related to Place and Damage/Count details
  FILTER (
    CONTAINS(STR(?property), "Hurricane") && 
    CONTAINS(STR(?property), "Place") &&
    (CONTAINS(STR(?property), "Damage") || CONTAINS(STR(?property), "NumberOf"))
  )

  OPTIONAL { ?property rdfs:label ?label }
  OPTIONAL { ?property rdfs:range ?range }

  # Extract temporal year if available in the property name (e.g., ...2018)
  OPTIONAL {
    BIND(REPLACE(STR(?property), ".*([0-9]{4})$", "$1") AS ?temporalYear)
    FILTER(REGEX(STR(?property), "[0-9]{4}$"))
  }
}
ORDER BY ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hazard ?dollarDamage ?affectedArea ?infrastructureDamage ?cropDamage ?startDate ?endDate
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?hazard .
  ?hazard rdf:type kwgl-ont:Tornado .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamage . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?hazard ?startDate ?endDate ?damageProperty ?damageValue
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?hazard .

  # Filter for storm-specific hazards (Hurricane, Tornado classes or Storm-related HazardTypes)
  { 
    ?hazard rdf:type kwgl-ont:Hurricane .
  } UNION { 
    ?hazard rdf:type kwgl-ont:Tornado .
  } UNION {
    ?hazard kwgl-ont:hasHazardType ?ht .
    FILTER (
      CONTAINS(LCASE(STR(?ht)), "storm") || 
      CONTAINS(LCASE(STR(?ht)), "hurricane") || 
      CONTAINS(LCASE(STR(?ht)), "tropical") ||
      CONTAINS(LCASE(STR(?ht)), "surge")
    )
  }

  # Temporal Extent
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }

  # Damage Details (on Place) - Generic filter for damage-related properties
  OPTIONAL { 
    ?place ?damageProperty ?damageValue .
    FILTER (
      CONTAINS(LCASE(STR(?damageProperty)), "dollarDamage") || 
      CONTAINS(LCASE(STR(?damageProperty)), "affectedArea") ||
      CONTAINS(LCASE(STR(?damageProperty)), "damageTo")
    )
  }

  # Damage Details (on HazardEvent) - Specific properties available in schema
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?eventArea . BIND("affectedAreaInAcres" AS ?damageProperty) BIND(?eventArea AS ?damageValue) }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . BIND("damageToInfrastructureInDollars" AS ?damageProperty) BIND(?infraDamage AS ?damageValue) }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?author ?firstName ?lastName
WHERE {
  ?author a coress-ont:Author .
  OPTIONAL {
    ?author coress-ont:isPerformedBy ?agent .
    ?agent coress-ont:hasFirstName ?firstName .
    ?agent coress-ont:hasFamilyName ?lastName .
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author ?advisor
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?publicationType
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?uni ?state (COUNT(?pub) AS ?publicationCount)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author a coress-ont:Role .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?uni .
      ?uni a coress-ont:University .
      ?uni coress-ont:atState ?state .
    }
    GROUP BY ?uni ?state
  }
  {
    SELECT ?s (MAX(?cnt) AS ?maxCount)
    WHERE {
      {
        SELECT ?u ?st (COUNT(?p) AS ?c)
        WHERE {
          ?p a coress-ont:Publication .
          ?p coress-ont:submittedBy ?a .
          ?a a coress-ont:Role .
          ?a coress-ont:isPerformedBy ?ag .
          ?ag coress-ont:worksInDepartment ?d .
          ?d coress-ont:departmentOf ?c .
          ?c coress-ont:collegeOf ?u .
          ?u a coress-ont:University .
          ?u coress-ont:atState ?st .
        }
        GROUP BY ?u ?st
      }
    }
    GROUP BY ?s
  }
  FILTER (?state = ?s && ?publicationCount = ?maxCount)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?hazardEvent
  ?name
  ?startDate
  ?endDate
  ?typeLabel
  ?areaInAcres
  ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasHazardType ?type .
    OPTIONAL { ?type rdfs:label ?typeLabel }
  }

  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?areaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
}
ORDER BY ?startDate

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?name ?totalCount WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name } .

  {
    SELECT (COUNT(*) AS ?totalCount) WHERE {
      ?x rdf:type kwgl-ont:Earthquake .
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?domain
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  # Ensure the attribute is related to geographical places (Place domain)
  OPTIONAL { ?attribute rdfs:domain ?domain . }

  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?domain)), "place")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?name ?startDate ?endDate ?deaths ?area ?hazardType ?typeLabel
WHERE {
  ?event rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?event kwgl-ont:hasName ?name }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL {
    ?event kwgl-ont:hasHazardType ?hazardType .
    OPTIONAL { ?hazardType rdfs:label ?typeLabel }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT
  ?hazardEvent
  ?hazardName
  ?hazardType
  ?affectedAreaInAcres
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
  ?numberOfDeaths
  ?startDate
  ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardName }

  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasHazardType ?typeUri .
    ?typeUri rdfs:label ?hazardType .
  }

  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?tornado ?place ?placeName ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?tornado rdf:type kwgl-ont:Tornado .

  ?tornado kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place rdfs:label ?placeName }

  OPTIONAL { ?tornado kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?tornado kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?tornado kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?tornado kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?tornado kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?tornado kwgl-ont:numberOfDeaths ?numberOfDeaths }
}
ORDER BY ?startDate ?placeName

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX terms: <http://purl.org/dc/terms/>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?event ?place ?placeName ?startDate ?endDate ?damageCrops ?damageInfra ?areaAcres ?hazardTypeURI
WHERE {
  # Filter for storm-specific hazard events using Class types or HazardType individuals
  {
    ?event rdf:type kwgl-ont:Hurricane .
    BIND(kwglr:hurricane AS ?hazardTypeURI)
  } UNION {
    ?event rdf:type kwgl-ont:Tornado .
    BIND(kwglr:tornado AS ?hazardTypeURI)
  } UNION {
    ?event kwgl-ont:hasHazardType kwglr:stormSurgeTide .
    BIND(kwglr:stormSurgeTide AS ?hazardTypeURI)
  }

  # Retrieve Temporal Extent (Start and End Dates)
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }

  # Relate to Geographical Place
  OPTIONAL { ?event kwgl-ont:hasImpacted ?place . 
             OPTIONAL { ?place kwgl-ont:hasName ?placeName . } }

  # Retrieve Damage Details associated with the Event
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfra . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?areaAcres . }
}
ORDER BY ?startDate

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?name ?startDate ?endDate ?hazardType ?typeLabel ?affectedArea ?deaths ?cropDamage ?infraDamage
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?hazardType rdfs:label ?typeLabel }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name ?diabetic ?obese ?povertyLine ?fireCount ?floodCount ?tornadoCount ?earthquakeCount
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:numberOfFiresImpactingPlace ?fireCount }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?floodCount }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?tornadoCount }
  OPTIONAL { ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?earthquakeCount }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?name (COUNT(?earthquake) AS ?totalCount)
WHERE {
  ?earthquake a kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name }
}
GROUP BY ?earthquake ?name

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place (COALESCE(?dollarDamage, 0) AS ?tornadoDollarDamage) (COALESCE(?numberOfTornadoes, 0) AS ?numberOfTornadoesCount)
WHERE {
  ?place a kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamage }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?numberOfTornadoes }

  FILTER(BOUND(?dollarDamage) || BOUND(?numberOfTornadoes))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?placeName ?stormSurgeDamage ?numberOfStormSurges
WHERE {
    ?place rdf:type kwgl-ont:Place .
    OPTIONAL { ?place kwgl-ont:hasName ?placeName }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage }
    OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?numberOfStormSurges }
    FILTER (BOUND(?stormSurgeDamage) || BOUND(?numberOfStormSurges))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?placeName ?attributeLabel ?value
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName } .
  ?place ?attrProp ?value .
  FILTER (isLiteral(?value) && regex(str(?attrProp), "Flood", "i"))
  OPTIONAL { ?attrProp rdfs:label ?attributeLabel }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazardEvent ?name ?startDate ?endDate ?areaInAcres ?deaths ?infraDamage ?cropDamage ?hazardTypeLabel
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?name }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?areaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?cropDamage }

  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasHazardType ?ht .
    OPTIONAL { ?ht rdfs:label ?hazardTypeLabel }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?event ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?placeName ?hazardTypeName ?damageValue ?propLabel
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?event .
  ?event kwgl-ont:hasHazardType ?hazardType .
  ?hazardType rdfs:label ?hazardTypeName .
  OPTIONAL {
    VALUES ?prop {
      kwgl-ont:dollarDamageOfFiresImpactingPlace
      kwgl-ont:dollarDamageOfFloodsImpactingPlace
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace
      kwgl-ont:dollarDamageOfLandslidesImpactingPlace
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace
      kwgl-ont:dollarDamageOfTornadoesImpactingPlace
    }
    ?place ?prop ?damageValue .
    ?prop rdfs:label ?propLabel .
  }
  OPTIONAL {
    ?place kwgl-ont:hasName ?placeName .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?place ?placeName 
       ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
       ?hurricaneDollarDamageTotal ?dollarDamage2018 ?dollarDamage2019 ?dollarDamage2020 ?dollarDamage2021 ?dollarDamage2022
       ?hurricaneCountTotal ?countHurricanes2018 ?countHurricanes2019 ?countHurricanes2020 ?countHurricanes2021 ?countHurricanes2022
WHERE {
  ?event a kwgl-ont:Hurricane .
  ?event kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }

  # Hurricane damage impact details on Place with temporal data (Years)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDollarDamageTotal }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?dollarDamage2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?dollarDamage2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?dollarDamage2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?dollarDamage2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?dollarDamage2022 }

  # Hurricane count impact details on Place with temporal data (Years)
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCountTotal }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?countHurricanes2018 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?countHurricanes2019 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?countHurricanes2020 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?countHurricanes2021 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?countHurricanes2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?event ?placeName ?startDate ?endDate ?cropsDamage ?infraDamage ?affectedArea
WHERE {
  ?event kwgl-ont:hasHazardType kwglr:tornado .

  ?event kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropsDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardEvent ?placeName ?damageToCrops ?damageToInfrastructure ?affectedArea ?numberOfDeaths ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Hurricane .

  OPTIONAL { ?hazardEvent kwgl-ont:hasImpacted ?place . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }

  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}
UNION
SELECT DISTINCT ?hazardEvent ?placeName ?damageToCrops ?damageToInfrastructure ?affectedArea ?numberOfDeaths ?startDate ?endDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:Tornado .

  OPTIONAL { ?hazardEvent kwgl-ont:hasImpacted ?place . }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCrops . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }

  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
