PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?univ ?count
WHERE {
  {
    SELECT ?state ?univ (COUNT(DISTINCT ?pub) AS ?count)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author a coress-ont:Author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?univ .
      ?univ a coress-ont:University .
      ?univ coress-ont:atState ?state .
    }
    GROUP BY ?state ?univ
  }

  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      SELECT ?state ?univ (COUNT(DISTINCT ?pub) AS ?c)
      WHERE {
        ?pub a coress-ont:Publication .
        ?pub coress-ont:submittedBy ?author .
        ?author a coress-ont:Author .
        ?author coress-ont:isPerformedBy ?agent .
        ?agent coress-ont:worksInDepartment ?dept .
        ?dept coress-ont:departmentOf ?college .
        ?college coress-ont:collegeOf ?univ .
        ?univ a coress-ont:University .
        ?univ coress-ont:atState ?state .
      }
      GROUP BY ?state ?univ
    }
    GROUP BY ?state
  }

  FILTER (?count = ?maxCount)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department (COUNT(DISTINCT ?agent) AS ?missingCount)
WHERE {
  ?department a coress-ont:Department .
  ?department coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fname }
}
GROUP BY ?department
ORDER BY DESC(?missingCount)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?hazard ?type ?hazardLabel ?name ?detailsURL ?timeValue
WHERE {
  ?hazard a ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { ?hazard rdfs:label ?rdfsLabel }
  OPTIONAL { ?hazard skos:prefLabel ?skosLabel }
  BIND(COALESCE(?skosLabel, ?rdfsLabel) AS ?hazardLabel)

  OPTIONAL { ?hazard kwg-ont:hasName ?name }
  OPTIONAL { ?hazard kwg-ont:detailsURL ?detailsURL }

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .
    OPTIONAL { ?timeEntity time:inXSDDate ?t1 }
    OPTIONAL { ?timeEntity time:inXSDDateTime ?t2 }
    OPTIONAL { 
      ?timeEntity time:hasBeginning ?beginning .
      OPTIONAL { ?beginning time:inXSDDate ?b1 }
      OPTIONAL { ?beginning time:inXSDDateTime ?b2 }
    }
  }
  BIND(COALESCE(?t1, ?t2, ?b1, ?b2) AS ?timeValue)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?place ?name
WHERE {
  { ?place a kwg-ont:AdministrativeRegion . }
  UNION
  { ?place a gnis:County . }
  UNION
  { ?place a usgs:State . }
  UNION
  { ?place a usgs:PopulatedPlace . }

  OPTIONAL { ?place skos:prefLabel ?name . }
  OPTIONAL { ?place gnis:officialName ?name . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
  {
    # Retrieve public health concerns (observations) associated with geographical places
    ?collection a kwg-ont:PublicHealthObservationCollection .
    ?collection sosa:hasFeatureOfInterest ?place .
    ?collection sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?healthAttribute .
  }
  UNION
  {
    # Retrieve health facility attributes (infrastructure) within geographical places
    ?facility a kwg-ont:HealthCareFacility .
    ?facility kwg-ont:sfWithin ?place .
    VALUES ?prop { kwg-ont:hospitalType kwg-ont:hospitalStatus kwg-ont:traumaCareLevel }
    ?facility ?prop ?healthAttribute .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT ?earthquake ?label (COUNT(*) AS ?totalCount)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
  { SELECT (COUNT(DISTINCT ?e) AS ?totalCount) WHERE { ?e a kwg-ont:Earthquake } }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?type ?attribute ?placeLabel
WHERE {
  { ?hazard a kwg-ont:NOAAHazardEvent } UNION { ?hazard a kwg-ont:StormTrack }

  ?hazard rdf:type ?type .

  OPTIONAL {
    ?hazard sosa:hasObservation ?obs .
    ?obs sosa:observedProperty ?attribute .
  }

  OPTIONAL {
    ?hazard kwg-ont:spatialRelation ?place .
    ?place rdfs:label ?placeLabel .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?place ?hazardLabel ?placeLabel ?temporalScope ?geometryWKT
WHERE {
  # Identify Flood Hazard Events based on specific subclasses of NOAAHazardEvent
  VALUES ?floodType { kwg-ont:NOAACoastalFlood kwg-ont:NOAAFlashFlood kwg-ont:NOAAFlood kwg-ont:NOAALakeshoreFlood }
  ?hazard a ?floodType .

  # Identify Geographical Places (Administrative Regions, Counties, States)
  ?place a ?placeType .
  FILTER (?placeType IN (kwg-ont:AdministrativeRegion, gnis:County, gnis:State))

  # Retrieve Spatial Relationship between Hazard and Place
  ?hazard kwg-ont:spatialRelation ?place .

  # Retrieve Hazard Details (Label, Temporal Scope)
  OPTIONAL { ?hazard rdfs:label ?hazardLabel }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?temporalScope }

  # Retrieve Place Details (Label)
  OPTIONAL { ?place rdfs:label ?placeLabel }

  # Retrieve Geometry WKT if available (using default geometry property common in GeoSPARQL features)
  OPTIONAL { 
    ?hazard geo:hasDefaultGeometry ?geom .
    ?geom geo:asWKT ?geometryWKT .
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?place ?placeLabel ?climateProperty ?propertyLabel ?anomalyValue
WHERE {
  ?obs a kwg-ont:ClimateObservation .
  ?obs sosa:hasFeatureOfInterest ?place .
  ?place rdf:type geo:Feature .
  OPTIONAL { ?place skos:prefLabel ?placeLabel }
  ?obs sosa:observedProperty ?climateProperty .
  ?climateProperty a kwg-ont:ClimateObservableProperty .
  OPTIONAL { ?climateProperty skos:prefLabel ?propertyLabel }
  OPTIONAL { 
    ?obs sosa:hasResult ?result .
    ?result a kwg-ont:ClimateDivisionObservationResult .
    ?result kwg-ont:anomaly ?anomalyValue .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?earthquake ?label ?type ?wkt ?timeScope
WHERE {
  ?earthquake rdf:type kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
  BIND (kwg-ont:Earthquake AS ?type)
  OPTIONAL { 
    ?earthquake geo:hasDefaultGeometry ?geom .
    ?geom geo:asWKT ?wkt .
  }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?timeScope }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazardEvent ?impactFactorLabel ?impactValue
WHERE {
  ?obs a kwg-ont:ImpactObservation .
  ?obs sosa:hasFeatureOfInterest ?hazardEvent .
  ?obs sosa:observedProperty ?factor .
  OPTIONAL { ?factor rdfs:label ?impactFactorLabel }
  OPTIONAL { ?obs sosa:hasSimpleResult ?impactValue }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hurricane ?place ?attribute ?damageDetail ?temporalScope ?timeValue
WHERE {
  # Identify Hurricane instances
  ?hurricane a kwg-ont:NOAAHurricane .

  # Related Geographical Place (Mandatory based on question "that are related")
  ?hurricane kwg-ont:sfWithin ?place .

  # Hurricane-specific hazard attributes via StormTrack Observations
  OPTIONAL {
    ?hurricane kwg-ont:hasStormTrack ?track .
    ?track sosa:hasObservation ?obs .
    ?obs sosa:observedProperty ?attribute .
  }

  # Damage impact details via Impact Observation Collections
  OPTIONAL {
    ?impactCol sosa:hasFeatureOfInterest ?hurricane .
    ?impactCol sosa:hasMember ?impObs .
    ?impObs sosa:observedProperty ?damageDetail .
  }

  # Temporal data
  OPTIONAL {
    ?hurricane kwg-ont:hasTemporalScope ?temporalScope .
    OPTIONAL { ?temporalScope time:inXSDDateTime ?timeValue }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?tornado ?temporalScope ?obsProperty ?result ?place
WHERE {
    ?tornado a kwg-ont:NOAATornado .

    # Temporal extent of the hazard
    OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?temporalScope . }

    # Damage details via Observations (Impact or Magnitude)
    ?obs sosa:hasFeatureOfInterest ?tornado ;
         a sosa:Observation ;
         sosa:observedProperty ?obsProperty ;
         sosa:hasResult ?result .

    # Related to a geographical place (Spatial relation if available, otherwise implicit via Feature)
    OPTIONAL { ?tornado kwg-ont:sfWithin ?place . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?damageTypeLabel ?timeStart ?timeEnd ?geometry ?placeName
WHERE {
  ?obs a kwg-ont:ImpactObservation .
  ?obs sosa:hasFeatureOfInterest ?event .

  # Filter for storm-specific hazards (NOAA Hazard Events)
  ?event rdf:type kwg-ont:NOAAHazardEvent .

  # Retrieve damage details (Observed Property)
  ?obs sosa:observedProperty ?damageType .
  ?damageType rdfs:label ?damageTypeLabel .

  # Retrieve Temporal Extent
  ?event kwg-ont:hasTemporalScope ?timeEntity .
  OPTIONAL { 
    { ?timeEntity a time:Instant ; time:inXSDDateTime ?timeStart }
    UNION
    { ?timeEntity a time:Interval ; time:hasBeginning ?begin ; time:hasEnd ?end . BIND(?begin AS ?timeStart) BIND(?end AS ?timeEnd) }
  }

  # Retrieve Geographical Place (Geometry or Administrative Region)
  OPTIONAL { ?event geo:asWKT ?geometry }
  OPTIONAL { 
    ?event kwg-ont:sfWithin ?place .
    ?place rdfs:label ?placeName .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author
WHERE {
  ?author a coresr-ont:Author .
