PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT ?hazard ?label ?disasterName ?fireName ?incidentName ?time
WHERE {
  ?hazard a kwg-ont:Hazard .

  # Retrieve generic label
  OPTIONAL { ?hazard rdfs:label ?label }

  # Retrieve specific name properties defined for Hazard subclasses in the schema
  OPTIONAL { ?hazard kwg-ont:hasDisasterName ?disasterName }
  OPTIONAL { ?hazard kwg-ont:hasFireName ?fireName }
  OPTIONAL { ?hazard kwg-ont:hasIncidentName ?incidentName }

  # Retrieve time information (directly on Hazard or via linked Observation Collections)
  OPTIONAL { 
    { ?hazard kwg-ont:hasTemporalScope ?time }
    UNION
    { ?obs sosa:hasFeatureOfInterest ?hazard . ?obs sosa:phenomenonTime ?time }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name WHERE {
  {
    ?place a kwg-ont:FederalJudicalDistrict ;
           kwg-ont:hasName ?name .
  } UNION {
    ?place a kwg-ont:Hospital ;
           kwg-ont:hospitalName ?name .
  } UNION {
    ?place a kwg-ont:Pharmacy ;
           kwg-ont:pharmacyName ?name .
  } UNION {
    ?place a kwg-ont:PublicHealthDepartment ;
           kwg-ont:publicHealthDepartmentName ?name .
  } UNION {
    ?place a kwg-ont:AirQualitySite ;
           kwg-ont:siteName ?name .
  } UNION {
    ?place a kwg-ont:RoadSegment ;
           kwg-ont:hasRoadName ?name .
  } UNION {
    ?place a kwg-ont:USClimateDivision ;
           kwg-ont:climateDivisionName ?name .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?earthquake ?totalCount
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  {
    SELECT (COUNT(*) AS ?totalCount)
    WHERE { ?x a kwg-ont:Earthquake }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?attr (COUNT(DISTINCT ?attr) AS ?totalCount) WHERE {
  {
    SELECT DISTINCT ?attr WHERE {
      ?coll a kwg-ont:TornadoMagnitudeObservationCollection .
      ?coll sosa:hasMember ?obs .
      ?obs sosa:observedProperty ?attr .
      ?obs sosa:hasFeatureOfInterest ?tornado .
      ?tornado a kwg-ont:NOAATornado .
    }
  }
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount) WHERE {
      ?coll a kwg-ont:TornadoMagnitudeObservationCollection .
      ?coll sosa:hasMember ?obs .
      ?obs sosa:observedProperty ?attr .
      ?obs sosa:hasFeatureOfInterest ?tornado .
      ?tornado a kwg-ont:NOAATornado .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?flood ?geom ?defaultGeom ?place ?relationType
WHERE {
  ?flood a kwg-ont:NOAAFlood .

  OPTIONAL { ?flood kwg-ont:hasGeometry ?geom }
  OPTIONAL { ?flood geo:hasDefaultGeometry ?defaultGeom }

  OPTIONAL { 
    ?flood kwg-ont:spatialRelation ?place .
    ?place a geo:Feature .
    BIND(kwg-ont:spatialRelation AS ?relationType)
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?earthquake ?type ?geometry ?timeScope ?observedProperty ?s2Cell ?adminRegion
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  ?earthquake rdf:type ?type .

  OPTIONAL { ?earthquake geo:hasDefaultGeometry ?geometry }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?timeScope }
  OPTIONAL { ?earthquake kwg-ont:sfWithin ?s2Cell }
  OPTIONAL { ?earthquake kwg-ont:spatialRelation ?adminRegion }

  OPTIONAL {
    ?collection sosa:hasFeatureOfInterest ?earthquake .
    ?collection sosa:hasMember ?obs .
    ?obs sosa:observedProperty ?observedProperty .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hurricane ?impactProperty ?magnitudeProperty ?phenomenonTime
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  OPTIONAL {
    ?impactCollection sosa:hasFeatureOfInterest ?hurricane ;
                      a kwg-ont:ImpactObservationCollection .
    ?impactCollection sosa:phenomenonTime ?time1 .
    ?impactCollection sosa:hasMember ?impactObs .
    ?impactObs a kwg-ont:ImpactObservation .
    ?impactObs sosa:observedProperty ?impactProperty .
  }

  OPTIONAL {
    ?magCollection sosa:hasFeatureOfInterest ?hurricane ;
                   a kwg-ont:MagnitudeObservationCollection .
    ?magCollection sosa:phenomenonTime ?time2 .
    ?magCollection sosa:hasMember ?magObs .
    ?magObs sosa:observedProperty ?magnitudeProperty .
  }

  BIND(COALESCE(?time1, ?time2) AS ?phenomenonTime)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?damageProperty ?timeExtent ?locationGeometry ?region
WHERE {
  ?collection a kwg-ont:ImpactObservationCollection .
  ?collection sosa:hasFeatureOfInterest ?hazard .
  ?hazard a kwg-ont:NOAATornado .

  ?collection sosa:hasMember ?observation .
  ?observation sosa:observedProperty ?damageProperty .

  OPTIONAL { ?collection sosa:phenomenonTime ?timeExtent }
  OPTIONAL { ?hazard geo:hasDefaultGeometry ?locationGeometry }
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?region }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?time ?property ?value
WHERE {
  ?hazard rdf:type ?Type .
  ?Type rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?time }
  OPTIONAL { ?hazard sosa:phenomenonTime ?time }
  OPTIONAL { ?hazard ?property ?value }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name
WHERE {
  { ?place a ?type . ?type rdfs:subClassOf* kwg-ont:Region }
  UNION
  { ?place a ?type . ?type rdfs:subClassOf* usgs:Terrain }
  UNION
  { ?place a ?type . ?type rdfs:subClassOf* usgs:SurfaceWater }
  UNION
  { ?place a ?type . ?type rdfs:subClassOf* usgs:BuiltUpArea }
  OPTIONAL { ?place rdfs:label ?name }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?place ?placeType ?healthConcern ?concernType ?obsProperty ?facilityName ?facilityType
WHERE {
  # Identify Geographical Places (Regions)
  ?place a geo:Feature .
  ?place rdfs:subClassOf* kwg-ont:Region .

  # Retrieve Place Type for context
  ?place a ?placeType .

  # Health Concerns: Hazards spatially related to the place
  OPTIONAL {
    ?healthConcern kwg-ont:spatialRelation ?place .
    ?healthConcern rdfs:subClassOf* kwg-ont:Hazard .
    ?healthConcern a ?concernType .
  }

  # Health Attributes: Observations linked to the place (e.g., Public Health Metrics)
  OPTIONAL {
    ?obs sosa:hasFeatureOfInterest ?place .
    ?obs sosa:observedProperty ?obsProperty .
  }

  # Health Infrastructure: Facilities located within the place
  OPTIONAL {
    ?facility kwg-ont:sfWithin ?place .
    ?facility rdfs:subClassOf* kwg-ont:HealthCareFacility .
    ?facility a ?facilityType .

    # Retrieve specific names if available based on schema definitions
    OPTIONAL { ?facility kwg-ont:hospitalName ?facilityName . }
    OPTIONAL { ?facility kwg-ont:pharmacyName ?facilityName . }
    OPTIONAL { ?facility kwg-ont:publicHealthDepartmentName ?facilityName . }
  }
}
ORDER BY ?place ?concernType ?obsProperty ?facilityType

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?attribute ?totalCount
WHERE {
  ?attribute rdf:type sosa:ObservableProperty .
  ?attribute rdf:type kwg-ont:MagnitudeObservableProperty .
  {
    SELECT (COUNT(*) AS ?totalCount)
    WHERE {
      ?a rdf:type sosa:ObservableProperty .
      ?a rdf:type kwg-ont:MagnitudeObservableProperty .
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?hazard ?property ?value
WHERE {
  { ?hazard a kwg-ont:NOAAHazardEvent . }
  UNION
  { ?hazard a kwg-ont:StormTrack . }
  UNION
  { ?hazard a kwg-ont:StormTracklet . }

  # Ensure the hazard is related to geographical places via geometry or spatial relation
  OPTIONAL { ?hazard geo:hasDefaultGeometry ?geom . }
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?place . }

  # Retrieve all available attributes and their details
  ?hazard ?property ?value .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?floodInstance ?type ?geometry ?place ?property ?value
WHERE {
  # Identify flood hazard instances by their specific types under NOAAHazardEvent
  ?floodInstance rdf:type ?type .
  VALUES ?floodType { kwg-ont:NOAAFlood kwg-ont:NOAAFlashFlood kwg-ont:NOAACoastalFlood kwg-ont:NOAALakeshoreFlood }
  ?type rdfs:subClassOf* ?floodType .

  # Retrieve geometry details (defined for geo:Feature)
  OPTIONAL { ?floodInstance geo:hasDefaultGeometry ?geometry . }
  OPTIONAL { ?floodInstance kwg-ont:hasGeometry ?geometry . }

  # Retrieve related geographical places via spatial relations
  OPTIONAL { ?floodInstance kwg-ont:spatialRelation ?place . 
             ?place rdf:type geo:Feature . }

  # Retrieve other available attributes/details
  OPTIONAL { ?floodInstance ?property ?value . 
             FILTER (?property != rdf:type && ?property != rdfs:subClassOf) }
}
ORDER BY ?type ?floodInstance

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?type ?startDate ?endDate ?deaths ?affectedArea
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea . }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?name ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?totalCount
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  {
    SELECT (COUNT(DISTINCT ?x) AS ?totalCount)
    WHERE { ?x rdf:type kwgl-ont:Earthquake }
  }
}
ORDER BY ?hazard

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute ?label ?totalCount WHERE {
  {
    SELECT (COUNT(DISTINCT ?attr) AS ?totalCount)
    WHERE {
      ?attr rdf:type owl:DatatypeProperty .
      FILTER(CONTAINS(LCASE(STR(?attr)), "tornado"))
      OPTIONAL { ?attr rdfs:domain kwgl-ont:Place }
    }
  }
  ?attribute rdf:type owl:DatatypeProperty .
  FILTER(CONTAINS(LCASE(STR(?attribute)), "tornado"))
  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attribute)), "stormsurge") ||
    CONTAINS(LCASE(STR(?attribute)), "tornado")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?deaths ?damage ?area ?type
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damage . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area . }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?name ?hazardType ?deaths ?cropDamage ?infraDamage ?area
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?event kwgl-ont:hasName ?name . }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType . }

  # Impact factor details associated with HazardEvents
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?area . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hazard ?fireDamage ?floodDamage ?hurricaneDamage ?landslideDamage ?stormSurgeDamage ?tornadoDamage ?cropDamage ?infrastructureDamage
WHERE {
  ?place kwgl-ont:impactedBy ?hazard .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?fireDamage . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamage . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?landslideDamage . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage . }

  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }
  OPTIONAL { ?attribute rdfs:range ?range . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "hurricane") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "hurricane")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?damageValue ?startDate ?endDate ?hazardType
WHERE {
  ?place rdf:type kwgl-ont:Place .

  # Retrieve storm-related damage details (Hurricane, Tornado, StormSurge)
  # Using generic properties which subsume specific year-based ones in the schema hierarchy
  OPTIONAL {
    { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageValue . }
    UNION
    { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?damageValue . }
    UNION
    { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?damageValue . }
  }

  # Retrieve temporal extent from linked HazardEvents
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?event .
    ?event rdf:type ?hazardType .
    FILTER ( ?hazardType IN (kwgl-ont:Hurricane, kwgl-ont:Tornado) )
    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }
  }

  # Ensure we have either damage or temporal info to be relevant
  FILTER (BOUND(?damageValue) || BOUND(?startDate))
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author
WHERE {
  ?author rdf:type coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department
WHERE {
  ?department rdf:type coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?submissionDate
WHERE {
    ?publication a coress-ont:Publication .
    ?publication coress-ont:dateOfSubmission ?submissionDate .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?publicationType
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?publicationType .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?firstName ?familyName ?department
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName }
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?college ?city
WHERE {
  ?college coress-ont:collegeOf ?university .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?dept (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
    ?agent a coress-ont:Agent .
    ?agent coress-ont:worksInDepartment ?dept .
    FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?dept
ORDER BY DESC(?missingFamilyNameCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?name ?type ?startDate ?endDate
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?name ?diabeticPercent ?obesePercent ?povertyLine
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticPercent }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesePercent }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?hazard ?name ?totalCount
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  { SELECT (COUNT(DISTINCT ?x) AS ?totalCount) WHERE { ?x rdf:type kwgl-ont:Earthquake } }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place ?placeName 
       ?hurricaneCount ?hurricaneDamage 
       ?tornadoCount ?tornadoDamage 
       ?stormSurgeCount ?stormSurgeDamage
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Hurricane Attributes
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }

  # Tornado Attributes
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?tornadoCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage }

  # Storm Surge Attributes
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?stormSurgeCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?place ?name ?placeType ?floodCount ?floodDamage
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasPlaceType ?placeType }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?floodCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamage }
  FILTER (BOUND(?floodCount) || BOUND(?floodDamage))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name ?avgTemp ?maxTemp ?minTemp ?heatDD ?coolDD
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }

  # Climate-specific attributes (Temperature and Degree Days)
  # Using super-properties to capture sub-property data via RDFS entailment or direct values
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?avgTemp }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?maxTemp }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?minTemp }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?heatDD }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?coolDD }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?startDate ?endDate ?deaths ?area ?damageCrops ?damageInfra ?type
WHERE {
  { ?hazard rdf:type kwgl-ont:Earthquake }
  UNION
  { ?hazard rdf:type kwgl-ont:HazardEvent ;
          kwgl-ont:hasHazardType kwglr:earthquake . }

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardEvent ?numberOfDeaths ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?hazard ?fireDamage ?floodDamage ?hurricaneDamage ?landslideDamage ?stormSurgeDamage ?tornadoDamage
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?hazard .
  ?hazard a kwgl-ont:HazardEvent .

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?fireDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?landslideDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place 
       ?hurricaneCount ?hurricaneDamage 
       ?hurricaneCount2018 ?hurricaneDamage2018
       ?hurricaneCount2019 ?hurricaneDamage2019
       ?hurricaneCount2020 ?hurricaneDamage2020
       ?hurricaneCount2021 ?hurricaneDamage2021
       ?hurricaneCount2022 ?hurricaneDamage2022
       ?startDate ?endDate 
       ?damageToCrops ?damageToInfrastructure
WHERE {
  ?place a kwgl-ont:Place .

  # Hurricane-specific hazard attributes related to Place
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage . }

  # Yearly hurricane attributes (Temporal granularity via property names)
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?hurricaneCount2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?hurricaneDamage2018 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?hurricaneCount2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?hurricaneDamage2019 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?hurricaneCount2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?hurricaneDamage2020 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?hurricaneCount2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?hurricaneDamage2021 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?hurricaneCount2022 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?hurricaneDamage2022 . }

  # Link to Hurricane Event for temporal data and additional damage details
  OPTIONAL { 
    ?place kwgl-ont:impactedBy ?event .
    ?event a kwgl-ont:Hurricane .

    # Temporal data from HazardEvent
    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }

    # Damage impact details from HazardEvent
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCrops . }
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure . }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?tornadoEvent ?placeName ?startDate ?endDate ?damageToInfrastructureInDollars ?damageToCropsInDollars ?affectedAreaInAcres ?numberOfDeaths
WHERE {
  ?tornadoEvent rdf:type kwgl-ont:Tornado .
  ?tornadoEvent kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?tornadoEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?tornadoEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardName ?placeName ?startDate ?endDate ?infrastructureDamage ?cropDamage ?affectedArea ?hurricaneDamage ?tornadoDamage ?stormSurgeDamage
WHERE {
  { ?hazard rdf:type kwgl-ont:Hurricane } 
  UNION 
  { ?hazard rdf:type kwgl-ont:Tornado }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

  ?place kwgl-ont:impactedBy ?hazard .

  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName }
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author
WHERE {
  ?author rdf:type coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title }
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author .
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state ?university (COUNT(?pub) AS ?publicationCount)
    WHERE {
      ?pub a coresr-ont:Publication .

      # Link Publication to University via Author, Department, College
      ?pub coresr-ont:submittedBy ?author .
      ?author coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .

      # Link University to State via Location
      ?university coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }

  {
    SELECT ?state (MAX(?cnt) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(?pub) AS ?cnt)
        WHERE {
          ?pub a coresr-ont:Publication .
          ?pub coresr-ont:submittedBy ?author .
          ?author coresr-ont:associatedWith ?dept .
          ?dept coresr-ont:partOf ?college .
          ?college coresr-ont:partOf ?university .
          ?university coresr-ont:locatedAt ?location .
          ?location coresr-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }

  FILTER(?publicationCount = ?maxCount)
}
ORDER BY DESC(?publicationCount)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication (COUNT(DISTINCT ?department) AS ?departmentCount)
WHERE {
  { ?publication coresr-ont:submittedBy ?role . }
  UNION
  { ?publication coresr-ont:hasContributor ?role . }

  ?role coresr-ont:isPerformedBy ?agent .
  ?agent coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?author ?firstName ?familyName
WHERE {
  ?author rdf:type coress-ont:Author .
  ?author coress-ont:isPerformedBy ?agent .
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName }
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?department WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?authorName (GROUP_CONCAT(DISTINCT ?field; SEPARATOR=", ") AS ?fields)
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
  ?publication coress-ont:submittedBy ?author .
  ?publication coress-ont:associatedFieldOfStudy ?field .

  OPTIONAL { ?author coress-ont:hasFirstName ?firstName }
  OPTIONAL { ?author coress-ont:hasFamilyName ?lastName }
  BIND(CONCAT(STR(?firstName), " ", STR(?lastName)) AS ?authorName)
}
GROUP BY ?author ?authorName
ORDER BY ?author

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?dept (COUNT(?agent) AS ?count)
WHERE {
    ?agent a coress-ont:Agent .
    ?agent coress-ont:worksInDepartment ?dept .
    MINUS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?dept
ORDER BY DESC(?count)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place skos:prefLabel ?name }
  OPTIONAL { ?place rdfs:label ?name_2 . BIND (COALESCE(?name, ?name_2) AS ?name) }
}
ORDER BY ?name

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthAttribute ?value
WHERE {
  {
    # Health Care Facility Attributes (Hospitals, Pharmacies, Public Health Depts)
    ?place a kwg-ont:Hospital .
    ?place ?healthAttribute ?value .
    FILTER (?healthAttribute != rdf:type)
  }
  UNION
  {
    ?place a kwg-ont:Pharmacy .
    ?place ?healthAttribute ?value .
    FILTER (?healthAttribute != rdf:type)
  }
  UNION
  {
    ?place a kwg-ont:PublicHealthDepartment .
    ?place ?healthAttribute ?value .
    FILTER (?healthAttribute != rdf:type)
  }
  UNION
  {
    # Public Health Observations linked to Geographical Places (Regions/Cells)
    ?collection sosa:hasFeatureOfInterest ?place .
    ?collection sosa:hasMember ?obs .
    ?obs a kwg-ont:PublicHealthObservation .
    ?obs sosa:observedProperty ?healthAttribute .
    OPTIONAL { ?obs sosa:hasResult ?value }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?attribute ?label
WHERE {
  ?attribute rdf:type kwg-ont:CensusObservableProperty .
  OPTIONAL { ?attribute rdfs:label ?label }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquake ?totalCount WHERE {
  ?earthquake rdf:type kwg-ont:Earthquake .
  {
    SELECT (COUNT(*) AS ?totalCount) WHERE {
      ?x rdf:type kwg-ont:Earthquake .
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?tornado) AS ?relatedTornadoCount)
WHERE {
  # Find Tornado Hazard Instances
  ?tornado a kwg-ont:NOAATornado .

  # Link to Geographical Place via Spatial Relation (Administrative Region/Feature)
  ?tornado kwg-ont:sfWithin ?place .
  ?place a geo:SpatialObject .

  # Find Hazard Attributes via Observations linked to the Tornado
  {
    ?obs sosa:hasFeatureOfInterest ?tornado .
  } UNION {
    ?collection a kwg-ont:TornadoMagnitudeObservationCollection ;
                sosa:hasMember ?obs .
  }

  # Retrieve the Attribute (Observed Property)
  ?obs sosa:observedProperty ?attribute .
}
GROUP BY ?attribute
ORDER BY ?attribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?attribute (COUNT(DISTINCT ?tornado) AS ?relatedTornadoCount)
WHERE {
