SELECT DISTINCT ?attribute (COUNT(DISTINCT ?tornado) AS ?relatedTornadoCount)
WHERE {
  # Find Tornado Hazard Instances
  ?tornado a kwg-ont:NOAATornado .

  # Link to Geographical Place via Spatial Relation (Administrative Region/Feature)
  ?tornado kwg-ont:sfWithin ?place .
  ?place a geo:SpatialObject .

  # Find Hazard Attributes via Observations linked to the Tornado
  {
    ?obs sosa:hasFeatureOfInterest ?tornado .
  } UNION {
    ?collection a kwg-ont:TornadoMagnitudeObservationCollection ;
                sosa:hasMember ?obs .
  }

  # Retrieve the Attribute (Observed Property)
  ?obs sosa:observedProperty ?attribute .
}
GROUP BY ?attribute
ORDER BY ?attribute

