PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?stormType ?superType ?property ?value
WHERE {
  ?stormType rdf:type owl:Class .
  ?stormType rdfs:subClassOf* kwg-ont:NOAAHazardEvent .
  OPTIONAL { ?stormType rdfs:subClassOf ?superType }
  OPTIONAL { ?stormType ?property ?value }
}
ORDER BY ?stormType ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>

SELECT DISTINCT ?hazard ?hazardType ?property ?value ?place ?placeLabel
WHERE {
  # Identify Flood-specific hazard instances or types based on class hierarchy and label
  ?hazard a ?hazardType .
  ?hazardType rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazardType rdfs:label ?typeLabel }
  FILTER (CONTAINS(LCASE(?typeLabel), "flood"))

  # Retrieve hazard attributes and details
  OPTIONAL { 
    ?hazard ?property ?value .
    FILTER(?property != rdf:type)
  }

  # Retrieve related geographical places via spatial relations or direct geometry properties
  OPTIONAL {
    ?hazard ?spatialRel ?place .
    VALUES (?spatialRel) { (kwg-ont:sfWithin) (kwg-ont:sfContains) (geo:hasGeometry) (kwg-ont:spatialRelation) }
    ?place a geo:Feature .
    OPTIONAL { ?place rdfs:label ?placeLabel }
  }
}
ORDER BY ?hazardType ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?tornado ?damageProperty ?damageCrop ?placeName ?temporalStart ?temporalEnd
WHERE {
  # Filter for tornado-specific hazards
  ?tornado a kwg-ont:NOAATornado .

  # Get temporal extent (if available)
  OPTIONAL { 
    ?tornado kwg-ont:hasTemporalScope ?tempScope .
    OPTIONAL { ?tempScope time:hasBeginning ?temporalStart }
    OPTIONAL { ?tempScope time:hasEnd ?temporalEnd }
  }

  # Get spatial relationship to geographical places (administrative regions)
  OPTIONAL { 
    ?tornado kwg-ont:sfWithin ?place .
    OPTIONAL { ?place rdfs:label ?placeName }
  }
  OPTIONAL {
    ?tornado kwg-ont:spatialRelation ?place2 .
    OPTIONAL { ?place2 rdfs:label ?placeName2 }
    BIND(?placeName2 AS ?placeName)
  }

  # Get damage/impact observation details if available
  OPTIONAL { 
    ?tornado sosa:hasObservation ?obs .
    ?obs a kwg-ont:ImpactObservation .
    OPTIONAL { ?obs sosa:observedProperty ?prop .
      BIND(REPLACE(STR(?prop), ".*damage", "") AS ?damageType) }
  }

  # Get damage-related observable properties directly (if linked)
  OPTIONAL { 
    ?tornado kwg-ont:sfWithin/place :kwg-ont:affectedBy ?impact .
    OPTIONAL { ?impact sosa:observedProperty kwg-ont:impactObservableProperty.damageProperty }
    BIND("property" AS ?damageProperty)
  }
  OPTIONAL { 
    ?tornado kwg-ont:sfWithin/place :kwg-ont:affectedBy ?impact2 .
    OPTIONAL { ?impact2 sosa:observedProperty kwg-ont:impactObservableProperty.damageCrop }
    BIND("crop" AS ?damageCrop)
  }
}
ORDER BY ?tornado ?temporalStart

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?damageTypeLabel ?temporalExtent ?geomWKT
WHERE {
  ?hazard rdf:type kwg-ont:NOAAHazardEvent .

  # Retrieve temporal extent (from Observation or Hazard)
  OPTIONAL { 
    ?obs sosa:hasFeatureOfInterest ?hazard .
    ?obs sosa:phenomenonTime ?temporalExtent .
    ?obs sosa:observedProperty ?damageType .
    FILTER EXISTS { ?damageType a kwg-ont:ImpactObservableProperty }
  }

  # Retrieve Damage Property Label (e.g., "damage property", "crop damage")
  OPTIONAL { ?damageType rdfs:label ?damageTypeLabel }

  # Retrieve Geographical Geometry/Place relation
  OPTIONAL { 
    ?hazard geo:hasGeometry ?geom .
    ?geom geo:asWKT ?geomWKT .
  }
}
ORDER BY ?temporalExtent ?hazard

# Note: This query retrieves storm-specific hazards (NOAAHazardEvent), their associated impact observations (damage details types), the time of occurrence, and their geometry. 
# If specific temporal values or location filters were provided in the question, WHERE clauses would be added to filter ?temporalExtent and ?geomWKT.

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?damageTypeLabel ?temporalExtent ?geomWKT
WHERE {
  ?hazard rdf:type kwg-ont:NOAAHazardEvent .

  # Retrieve temporal extent and damage details from linked observations
  OPTIONAL { 
    ?obs sosa:hasFeatureOfInterest ?hazard .
    ?obs sosa:phenomenonTime ?temporalExtent .
    ?obs sosa:observedProperty ?damageType .
    FILTER EXISTS { ?damageType rdf:type kwg-ont:ImpactObservableProperty }
  }

  # Retrieve the human-readable label for the damage type
  OPTIONAL { ?damageType rdfs:label ?damageTypeLabel }

  # Retrieve geographical place information (Geometry)
  OPTIONAL { 
    ?hazard geo:hasGeometry ?geom .
    ?geom geo:asWKT ?geomWKT .
  }
}
ORDER BY ?temporalExtent ?hazard

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?author
WHERE {
  ?author rdf:type coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:hasIdentifier ?doiNode .
  ?doiNode coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?author ?advisor
WHERE {
  ?author a coresr-ont:Author .
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state ?university (COUNT(?pub) AS ?publicationCount)
    WHERE {
      ?pub a coresr-ont:Publication .
      ?pub coresr-ont:submittedBy ?authorRole .
      ?agent coresr-ont:performsRole ?authorRole .
      ?agent coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .
      ?university a coresr-ont:University .
      ?university coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(?pub) AS ?c)
        WHERE {
          ?pub a coresr-ont:Publication .
          ?pub coresr-ont:submittedBy ?authorRole .
          ?agent coresr-ont:performsRole ?authorRole .
          ?agent coresr-ont:associatedWith ?dept .
          ?dept coresr-ont:partOf ?college .
          ?college coresr-ont:partOf ?university .
          ?university a coresr-ont:University .
          ?university coresr-ont:locatedAt ?loc .
          ?loc coresr-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER (?publicationCount = ?maxCount)
}
ORDER BY ?state DESC(?publicationCount)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub
WHERE {
  ?pub a coresr-ont:Publication .

  { 
    ?pub coresr-ont:submittedBy ?role .
  } UNION {
    ?role coresr-ont:contributedTo ?pub .
  }

  ?role coresr-ont:isPerformedBy ?agent .
  ?agent coresr-ont:associatedWith ?dept .
}
GROUP BY ?pub
HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .

  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contactInfo .
    ?contactInfo rdf:type coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?label ?timeValue
WHERE {
  ?hazard rdf:type/rdfs:subClassOf* kwg-ont:Hazard .
  OPTIONAL { ?hazard rdfs:label ?label }
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .
    OPTIONAL { ?timeEntity time:inXSDDateTime ?timeValue }
  }
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?place ?name
WHERE {
  ?place a geo:Feature .
  OPTIONAL { ?place rdfs:label ?name }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?placeName ?healthAttributeLabel ?value
WHERE {
  {
    # Public Health Observations linked to Places (Regions)
    ?obs a kwg-ont:PublicHealthObservation .
    ?obs sosa:hasFeatureOfInterest ?geoPlace .
    ?obs sosa:observedProperty ?attr .
    OPTIONAL { ?obs sosa:result ?value }
    OPTIONAL { ?attr rdfs:label ?healthAttributeLabel }
  } UNION {
    # Census Observations linked to Places (MSA)
    ?obs a kwg-ont:CensusACS5YearEstimatesObservation .
    ?obs sosa:hasFeatureOfInterest ?geoPlace .
    ?obs sosa:observedProperty ?attr .
    OPTIONAL { ?obs sosa:result ?value }
    OPTIONAL { ?attr rdfs:label ?healthAttributeLabel }
  } UNION {
    # Vulnerability Observations linked to Places (Regions)
    ?obs a kwg-ont:VulnerabilityObservation .
    ?obs sosa:hasFeatureOfInterest ?geoPlace .
    ?obs sosa:observedProperty ?attr .
    OPTIONAL { ?obs sosa:result ?value }
    OPTIONAL { ?attr rdfs:label ?healthAttributeLabel }
  } UNION {
    # Health Facility Attributes (Hospitals, Pharmacies, etc. as Places)
    ?geoPlace a kwg-ont:HealthCareFacility .
    ?geoPlace geo:hasDefaultGeometry ?geom .
    OPTIONAL { ?geoPlace rdfs:label ?placeName }
    # Hospital Status
    { ?geoPlace kwg-ont:hospitalStatus ?value ; 
      (kwg-ont:hospitalStatus) ?attrUri . BIND("Hospital Status" AS ?healthAttributeLabel) } UNION
    # Number of Beds
    { ?geoPlace kwg-ont:noHospitalBeds ?value ; 
      (kwg-ont:noHospitalBeds) ?attrUri . BIND("Number of Hospital Beds" AS ?healthAttributeLabel) } UNION
    # Hospital Type
    { ?geoPlace kwg-ont:hospitalType ?value ; 
      (kwg-ont:hospitalType) ?attrUri . BIND("Hospital Type" AS ?healthAttributeLabel) } UNION
    # Helipad Availability
    { ?geoPlace kwg-ont:helipadAvailability ?value ; 
      (kwg-ont:helipadAvailability) ?attrUri . BIND("Helipad Availability" AS ?healthAttributeLabel) }
  }
  OPTIONAL { ?geoPlace rdfs:label ?placeName }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
SELECT ?earthquake ?totalCount WHERE {
  ?earthquake a kwg-ont:Earthquake .
  {
    SELECT (COUNT(*) AS ?totalCount) WHERE {
      ?e a kwg-ont:Earthquake .
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?attribute ?totalCount
WHERE {
  {
    SELECT DISTINCT ?attribute
    WHERE {
      ?tornado rdf:type kwg-ont:NOAATornado .
      ?tornado kwg-ont:spatialRelation ?place .
      ?place rdf:type geo:Feature .
      ?collection sosa:hasFeatureOfInterest ?tornado .
      ?collection sosa:observedProperty ?attribute .
    }
  }
  {
    SELECT (COUNT(*) AS ?totalCount)
    WHERE {
      {
        SELECT DISTINCT ?attribute
        WHERE {
          ?tornado rdf:type kwg-ont:NOAATornado .
          ?tornado kwg-ont:spatialRelation ?place .
          ?place rdf:type geo:Feature .
          ?collection sosa:hasFeatureOfInterest ?tornado .
          ?collection sosa:observedProperty ?attribute .
        }
      }
    }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?earthquake ?geom ?timeScope ?obsProp ?result
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake geo:hasDefaultGeometry ?geom }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?timeScope }
  OPTIONAL {
    ?obs sosa:hasFeatureOfInterest ?earthquake .
    ?obs a sosa:Observation .
    ?obs sosa:observedProperty ?obsProp .
    ?obs sosa:hasSimpleResult ?result .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?observation ?observedProperty ?hazard ?geometry ?region ?timeExtent
WHERE {
  ?collection a kwg-ont:ImpactObservationCollection .
  ?collection sosa:hasMember ?observation .
  ?collection sosa:hasFeatureOfInterest ?hazard .

  # Filter for storm-specific hazards (NOAAHazardEvent includes Hurricane, Tornado, etc.)
  ?hazard a kwg-ont:NOAAHazardEvent .

  # Retrieve damage details (observed property)
  ?observation sosa:observedProperty ?observedProperty .

  # Retrieve geographical place information (Geometry or related Region)
  OPTIONAL { ?hazard geo:hasGeometry ?geometry }
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?region }

  # Retrieve temporal extent associated with the observation collection or hazard
  OPTIONAL { ?collection sosa:phenomenonTime ?timeExtent }
  OPTIONAL { ?hazard kwg-ont:hasTemporalScope ?timeExtent }
}

