SELECT ?univ ?state ?count
WHERE {
  {
    SELECT ?univ ?state (COUNT(?pub) AS ?count)
    WHERE {
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?univ .
      ?univ coress-ont:atState ?state .
    }
    GROUP BY ?univ ?state
  }
  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?u ?s (COUNT(?p) AS ?c)
        WHERE {
          ?p coress-ont:submittedBy ?a .
          ?a coress-ont:isPerformedBy ?ag .
          ?ag coress-ont:worksInDepartment ?d .
          ?d coress-ont:departmentOf ?col .
          ?col coress-ont:collegeOf ?u .
          ?u coress-ont:atState ?s .
        }
        GROUP BY ?u ?s
      }
    }
    GROUP BY ?state
  }
  FILTER (?count = ?maxCount)
}
ORDER BY ?state ?count DESC

