      ?otherUniv coresr-ont:locatedAt ?loc2 .
      ?loc2 coresr-ont:atState ?state2 .
    }
    GROUP BY ?state2 ?otherUniv
    FILTER (?state = ?state2 && ?count < ?otherCount)
  }
}

