      ?pub a coresr-ont:Publication .
      ?pub coresr-ont:submittedBy ?role .
      ?role coresr-ont:isPerformedBy ?agent .
      ?agent coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?univ .
    }
    GROUP BY ?univ ?state
  }
  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?u ?s (COUNT(DISTINCT ?p) AS ?c)
        WHERE {
          ?u a coresr-ont:University .
          ?u coresr-ont:locatedAt ?loc .
          ?loc coresr-ont:atState ?s .

          ?p a coresr-ont:Publication .
          ?p coresr-ont:submittedBy ?role .
          ?role coresr-ont:isPerformedBy ?agent .
          ?agent coresr-ont:associatedWith ?dept .
          ?dept coresr-ont:partOf ?college .
          ?college coresr-ont:partOf ?u .
        }
        GROUP BY ?u ?s
      }
    }
    GROUP BY ?state
  }
  FILTER(?count = ?maxCount)
}
ORDER BY ?state DESC(?count)

