PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?pub
WHERE {
  SELECT ?pub (COUNT(DISTINCT ?dept) AS ?deptCount)
  WHERE {
    # Path via Author Role
    {
      ?pub coresr-ont:submittedBy ?authorRole . 
      ?authorRole a coresr-ont:Author . 
      ?agent1 coresr-ont:performsRole ?authorRole . 
      ?agent1 coresr-ont:associatedWith ?dept .
    }
    UNION
    # Path via Contributor Role
    {
      ?contributorRole coresr-ont:contributedTo ?pub . 
      ?contributorRole a coresr-ont:Contributor . 
      ?agent2 coresr-ont:performsRole ?contributorRole . 
      ?agent2 coresr-ont:associatedWith ?dept .
    }
  }
  GROUP BY ?pub
  HAVING (COUNT(DISTINCT ?dept) > 1)
}

