PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?name 
       ?numFloods ?damageFloods 
       ?numFloods2018 ?numFloods2019 ?numFloods2020 ?numFloods2021 ?numFloods2022
       ?damageFloods2018 ?damageFloods2019 ?damageFloods2020 ?damageFloods2021 ?damageFloods2022
WHERE {
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?name }

  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numFloods }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damageFloods }

  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?numFloods2018 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?numFloods2019 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?numFloods2020 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?numFloods2021 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?numFloods2022 }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?damageFloods2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?damageFloods2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?damageFloods2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?damageFloods2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?damageFloods2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?earthquake ?name ?type ?startDate ?endDate ?deaths ?affectedArea ?damageToInfra ?damageToCrops
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name . }
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?type . }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea . }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfra . }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCrops . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazardEvent ?hazardType ?numberOfDeaths ?damageToCropsInDollars ?damageToInfrastructureInDollars ?affectedAreaInAcres
WHERE {
  ?hazardEvent a kwgl-ont:HazardEvent .

  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?hazardType ?damageToCropsInDollars ?damageToInfrastructureInDollars ?affectedAreaInAcres ?numberOfDeaths 
       ?dollarDamageOfFiresImpactingPlace ?dollarDamageOfFloodsImpactingPlace ?dollarDamageOfHurricanesImpactingPlace 
       ?dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?hazardEvent .
  ?hazardEvent a kwgl-ont:HazardEvent .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?hazardEvent kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageOfFiresImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageOfHurricanesImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageOfLandslidesImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageOfStormSurgesImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?place ?hurricaneCount ?hurricaneDamage ?eventName ?startDate ?endDate ?eventInfrastructureDamage ?eventCropDamage ?affectedAreaInAcres ?numberOfDeaths
WHERE {
  ?place a kwgl-ont:Place .

  # Hurricane-specific hazard attributes available on the Place
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }

  # Link to specific Hurricane HazardEvents for temporal data and detailed damage impact
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?event .
    ?event a kwgl-ont:Hurricane .

    # Temporal data of the event
    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

    # Damage impact details available on HazardEvents
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?eventInfrastructureDamage }
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?eventCropDamage }
    OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
    OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }

    # Optional event name if available
    OPTIONAL { ?event kwgl-ont:hasName ?eventName }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?tornadoEvent ?placeName ?placeType ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?dollarDamageOfTornadoesImpactingPlace
WHERE {
  ?tornadoEvent rdf:type kwgl-ont:HazardEvent .
  ?tornadoEvent kwgl-ont:hasHazardType kwglr:tornado .
  OPTIONAL { ?tornadoEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?tornadoEvent kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?tornadoEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?tornadoEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?tornadoEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }

  ?place kwgl-ont:impactedBy ?tornadoEvent .
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?place kwgl-ont:hasPlaceType ?placeType }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageOfTornadoesImpactingPlace }
}

