PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?label ?timeValue
WHERE {
  ?hazard rdf:type ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { ?hazard rdfs:label ?label }

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .

    # Case 1: Time is an Instant with direct dateTime
    OPTIONAL { 
      ?timeEntity time:inXSDDateTimeStamp ?timeValue . 
    }

    # Case 2: Time is an Interval, get start time
    OPTIONAL {
      ?timeEntity time:hasBeginning ?startInstant .
      ?startInstant time:inXSDDateTimeStamp ?startTime .
      BIND(?startTime AS ?timeValue)
    }
  }
}

PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?place ?name
WHERE {
  { ?place a geo:Feature }
  UNION
  { ?place a usgs:Feature }

  OPTIONAL { 
    ?place rdfs:label ?name .
  }
  OPTIONAL {
    ?place gnis:officialName ?gnisName .
    FILTER(!bound(?name))
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?label (COUNT(?all) AS ?totalCount)
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
  {
    SELECT (COUNT(*) as ?all)
    WHERE { ?x a kwg-ont:Earthquake }
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?flood ?geometry ?temporalScope ?segment ?place ?placeLabel
WHERE {
  { ?flood a kwg-ont:NOAAFlood }
  UNION { ?flood a kwg-ont:NOAAFlashFlood }
  UNION { ?flood a kwg-ont:NOAACoastalFlood }
  UNION { ?flood a kwg-ont:NOAALakeshoreFlood }

  OPTIONAL { ?flood geo:hasGeometry ?geometry }
  OPTIONAL { ?flood kwg-ont:hasTemporalScope ?temporalScope }
  OPTIONAL { ?flood kwg-ont:hasSegment ?segment }
  OPTIONAL { ?flood kwg-ont:spatialRelation ?place }
  OPTIONAL { ?place rdfs:label ?placeLabel }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?earthquake ?type ?geometry ?temporalScope ?observedProperty ?result
WHERE {
  ?earthquake a kwg-ont:Earthquake .

  OPTIONAL { ?earthquake rdf:type ?type }
  OPTIONAL { ?earthquake geo:hasGeometry ?geometry }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?temporalScope }

  OPTIONAL { 
    ?obs sosa:hasFeatureOfInterest ?earthquake .
    ?obs sosa:observedProperty ?observedProperty .
    ?obs sosa:hasSimpleResult ?result .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?hurricane ?hazardAttrProp ?hazardAttrResult ?impactProp ?impactResult ?temporalScope ?obsTime ?location ?regionName
WHERE {
  # Identify Hurricane Hazard Events
  ?hurricane a kwg-ont:NOAAHurricane .

  # Get Temporal Scope of the Hazard Event
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?temporalScope . }

  # Get Geographical Place (Geometry or Administrative Region)
  OPTIONAL { ?hurricane geo:hasGeometry ?location . }
  OPTIONAL { 
    ?hurricane kwg-ont:spatialRelation ?region .
    ?region rdfs:label ?regionName .
  }

  # Hazard Attributes (via Magnitude Observations linked to the hazard)
  OPTIONAL {
    ?magObs sosa:hasFeatureOfInterest ?hurricane .
    ?magObs a kwg-ont:MagnitudeObservation .
    ?magObs sosa:observedProperty ?hazardAttrProp .
    ?magObs sosa:hasSimpleResult ?hazardAttrResult .
    OPTIONAL { ?magObs sosa:phenomenonTime ?obsTime . }
  }

  # Damage Impact Details (via Impact Observations linked to the hazard)
  OPTIONAL {
    ?impactObs sosa:hasFeatureOfInterest ?hurricane .
    ?impactObs a kwg-ont:ImpactObservation .
    ?impactObs sosa:observedProperty ?impactProp .
    ?impactObs sosa:hasSimpleResult ?impactResult .
    OPTIONAL { ?impactObs sosa:phenomenonTime ?obsTime . }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?hazard ?name ?startDate ?endDate ?type ?areaInAcres ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?areaInAcres }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?percentDiabetic ?percentObese ?percentBelowPovertyLine
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?percentDiabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?percentObese }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?percentBelowPovertyLine }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?placeName ?population ?households ?povertyLine ?diabeticPercent ?obesePercent
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticPercent }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesePercent }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?attributeName ?value (COUNT(?triples) AS ?totalCount)
WHERE {
    {
        SELECT ?place ?attributeName ?value (COUNT(*) as ?triples)
        WHERE {
            ?place a kwgl-ont:Place .
            {
                ?place kwgl-ont:numberOfTornadoesImpactingPlace ?value .
                BIND("numberOfTornadoesImpactingPlace" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value .
                BIND("dollarDamageOfTornadoesImpactingPlace" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:numberOfTornadoesImpactingPlace2018 ?value .
                BIND("numberOfTornadoesImpactingPlace2018" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?value .
                BIND("dollarDamageOfTornadoesImpactingPlace2018" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:numberOfTornadoesImpactingPlace2019 ?value .
                BIND("numberOfTornadoesImpactingPlace2019" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?value .
                BIND("dollarDamageOfTornadoesImpactingPlace2019" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:numberOfTornadoesImpactingPlace2020 ?value .
                BIND("numberOfTornadoesImpactingPlace2020" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?value .
                BIND("dollarDamageOfTornadoesImpactingPlace2020" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:numberOfTornadoesImpactingPlace2021 ?value .
                BIND("numberOfTornadoesImpactingPlace2021" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?value .
                BIND("dollarDamageOfTornadoesImpactingPlace2021" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:numberOfTornadoesImpactingPlace2022 ?value .
                BIND("numberOfTornadoesImpactingPlace2022" AS ?attributeName)
            } UNION {
                ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?value .
                BIND("dollarDamageOfTornadoesImpactingPlace2022" AS ?attributeName)
            }
        }
    }
}
GROUP BY ?place ?attributeName ?value

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT ?placeName ?hazardEventName ?stormType ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  VALUES ?stormType { kwglr:hurricane kwglr:tropicalStorm kwglr:winterStorm kwglr:stormSurgeTide kwglr:thunderstormWind }
  ?hazardEvent kwgl-ont:hasHazardType ?stormType .

  ?hazardEvent kwgl-ont:hasImpacted ?place .
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hazardEventName }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?name ?damage ?count 
       ?damage2018 ?damage2019 ?damage2020 ?damage2021 ?damage2022
       ?count2018 ?count2019 ?count2020 ?count2021 ?count2022
WHERE {
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?name }

  # General Flood Attributes
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?damage }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?count }

  # Specific Yearly Flood Attributes (Dollars)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?damage2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?damage2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?damage2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?damage2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?damage2022 }

  # Specific Yearly Flood Attributes (Count)
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?count2018 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?count2019 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?count2020 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?count2021 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?count2022 }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName 
       ?averageCoolingDegreeDaysPerMonth ?averageHeatingDegreeDaysPerMonth 
       ?averageMonthlyTemperatureInCelsius ?maximumMonthlyTemperatureInCelsius ?minimumMonthlyTemperatureInCelsius
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?averageCoolingDegreeDaysPerMonth }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?averageHeatingDegreeDaysPerMonth }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsius ?averageMonthlyTemperatureInCelsius }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsius ?maximumMonthlyTemperatureInCelsius }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsius ?minimumMonthlyTemperatureInCelsius }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?startDate ?endDate ?deaths ?areaInAcres ?damageCrops ?damageInfra ?type
WHERE {
  ?hazard rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?areaInAcres }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  ?hazard kwgl-ont:hasHazardType ?type .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardEvent ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?hasName ?hasStartDate ?hasEndDate
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?hasName }
  OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?hasStartDate }
  OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?hasEndDate }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazardEvent ?damageToCropsInDollars ?damageToInfrastructureInDollars ?affectedAreaInAcres ?place ?dollarDamage
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .

  # Damage details on HazardEvent
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }

  # Impacted places and their damage details from Place properties
  OPTIONAL { 
    ?hazardEvent kwgl-ont:hasImpacted ?place .
    ?place rdf:type kwgl-ont:Place .

    # Get dollar damage values from place for various hazard types
    { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamage }
    UNION
    { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamage }
    UNION
    { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamage }
    UNION
    { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamage }
    UNION
    { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamage }
    UNION
    { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamage }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?placeName ?startDate ?endDate 
    ?hurricaneTotalDamage ?hurrTotalCount
    ?damage2018 ?count2018 ?damage2019 ?count2019 ?damage2020 ?count2020 ?damage2021 ?count2021 ?damage2022 ?count2022
    ?cropsDamage ?infraDamage ?deaths
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  ?place kwgl-ont:impactedBy ?event .

  # Check if the impacting event is specifically a Hurricane (class or type)
  { ?event a kwgl-ont:Hurricane } 
  UNION 
  { ?event kwgl-ont:hasHazardType kwglr:hurricane }

  # Temporal data from HazardEvent
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  # Damage impact details from HazardEvent
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropsDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }

  # Hurricane-specific hazard attributes related to the Place (Aggregated/Yearly)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneTotalDamage }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurrTotalCount }

  # Yearly Damage and Counts for temporal data on Place side (2018-2022)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damage2018 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?count2018 }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?damage2019 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?count2019 }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?damage2020 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?count2020 }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?damage2021 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?count2021 }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?damage2022 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?count2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardName ?placeName ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars
WHERE {
  ?hazard kwgl-ont:hasHazardType kwglr:tornado .
  ?hazard kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?eventStartDate ?eventEndDate ?damageToCropsInDollars ?damageToInfrastructureInDollars ?hazardTypeLabel
WHERE {
  ?event a kwgl-ont:HazardEvent .
  ?event kwgl-ont:hasHazardType ?hazardType .
  VALUES ?hazardType { 
    kwglr:hurricane kwglr:tornado kwglr:winterStorm kwglr:blizzard 
    kwglr:flashFlood kwglr:coastalFlood kwglr:iceStorm kwglr:frostFreeze 
    kwglr:heavySnow kwglr:tropicalDepression kwglr:tropicalStorm 
    kwglr:waterspout kwglr:stormSurgeTide kwglr:dustStorm
  }
  ?event kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?event kwgl-ont:hasStartDate ?eventStartDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?eventEndDate . }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT ?hazard ?label ?timeValue WHERE {
  ?hazard rdf:type ?class .
  ?class rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { ?hazard rdfs:label ?label }

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .

    OPTIONAL { ?timeEntity time:inXSDDateTime ?timeValue }
    OPTIONAL { 
      ?timeEntity time:inXSDDate ?dateVal . 
      FILTER(!BOUND(?timeValue)) 
      BIND(?dateVal AS ?timeValue) 
    }
    OPTIONAL { 
      ?timeEntity time:inXSDYear ?yearVal . 
      FILTER(!BOUND(?timeValue)) 
      BIND(?yearVal AS ?timeValue) 
    }
  }
}

PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
SELECT DISTINCT ?place ?name WHERE {
  VALUES ?type { usgs:Feature kwg-ont:AdministrativeRegion gnis:State gnis:County }
  ?place rdf:type ?type .
  OPTIONAL { ?place rdfs:label ?name }
  OPTIONAL { 
    ?place gnis:officialName ?oname .
    FILTER(!BOUND(?name))
    BIND (?oname AS ?name) 
  }
  OPTIONAL { 
    ?place gnis:stateName ?sname .
    FILTER(!BOUND(?name))
    BIND (?sname AS ?name) 
  }
  OPTIONAL { 
    ?place gnis:countyName ?cname .
    FILTER(!BOUND(?name))
    BIND (?cname AS ?name) 
  }
  FILTER(BOUND(?name))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?geographicalPlace ?publicHealthAttribute ?observedPropertyLabel ?resultValue WHERE {
  ?collection a kwg-ont:PublicHealthObservationCollection ;
              sosa:hasFeatureOfInterest ?geographicalPlace .

  FILTER(?geographicalPlace != "" && ?geographicalPlace IS IRI)

  OPTIONAL {
    ?collection sosa:hasMember ?observation .
    ?observation sosa:observedProperty ?publicHealthAttribute ;
                 a kwg-ont:PublicHealthObservableProperty .

    ?publicHealthAttribute rdfs:label ?observedPropertyLabel .

    OPTIONAL {
      ?observation sosa:hasSimpleResult ?resultValue .
    }
  }
}

PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT ?earthquake ?totalCount
WHERE {
  ?earthquake a kwg-ont:Earthquake .
  OPTIONAL { ?earthquake rdfs:label ?label }
  {
    SELECT (COUNT(*) AS ?total)
    WHERE { ?any_earthquake a kwg-ont:Earthquake }
  }
  BIND(?total AS ?totalCount)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?attr (COUNT(DISTINCT ?allAttr) AS ?totalCount)
WHERE {
  {
    SELECT DISTINCT ?allAttr WHERE {
      ?tornado a kwg-ont:NOAATornado ;
               kwg-ont:spatialRelation ?place .
      ?obs sosa:hasFeatureOfInterest ?tornado ;
           sosa:observedProperty ?allAttr .
      ?place rdfs:subClassOf* geo:Feature | a geo:Feature . 
    }
  }
  BIND(?allAttr AS ?attr)
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hazard ?stormTypeLabel ?locationGeometry ?regionName ?observedProperty ?attributeResult
WHERE {
  {
    ?hazard rdf:type ?class .
    FILTER(?class = kwg-ont:NOAAHazardEvent || EXISTS { ?class rdfs:subClassOf* kwg-ont:NOAAHazardEvent })
    OPTIONAL { ?class rdfs:label ?stormTypeLabel }
  } UNION {
    ?hazard rdf:type kwg-ont:StormTracklet .
    OPTIONAL { ?hazard rdfs:label ?stormTypeLabel }
  }

  ?hazard geo:hasGeometry ?locationGeometry .

  OPTIONAL { 
    ?hazard kwg-ont:spatialRelation ?place .
    ?place rdfs:label ?regionName .
  }

  ?obs sosa:hasFeatureOfInterest ?hazard .
  ?obs sosa:observedProperty ?observedProperty .
  OPTIONAL { ?obs sosa:hasSimpleResult ?attributeResult }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?floodEvent ?geom ?temporalScope ?segment ?place ?placeLabel ?placeType
WHERE {
  VALUES ?floodType { 
    kwg-ont:NOAAFlood 
    kwg-ont:NOAAFlashFlood 
    kwg-ont:NOAACoastalFlood 
    kwg-ont:NOAALakeshoreFlood 
  }

  ?floodEvent a ?floodType .

  OPTIONAL { ?floodEvent geo:hasGeometry ?geom . }
  OPTIONAL { ?floodEvent kwg-ont:hasTemporalScope ?temporalScope . }
  OPTIONAL { ?floodEvent kwg-ont:hasSegment ?segment . }

  ?floodEvent kwg-ont:spatialRelation ?place .
  OPTIONAL { ?place rdfs:label ?placeLabel . }
  OPTIONAL { ?place a ?placeType . }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?placeLabel ?attributeName
WHERE {
    ?observation a kwg-ont:ClimateDivisionObservationResult .
    ?observation sosa:hasFeatureOfInterest ?place .
    ?observation sosa:observedProperty ?prop .
    ?prop rdfs:subClassOf* kwg-ont:ClimateObservableProperty .

    OPTIONAL { ?place rdfs:label ?placeLabel }
    OPTIONAL { ?prop rdfs:label ?attributeName }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?type ?depth ?magnitude ?magType ?status ?locationSource ?geometryDetail ?temporalScope
WHERE {
  ?earthquake a kwg-ont:Earthquake .

  # Get earthquake type information if available
  OPTIONAL { ?earthquake rdfs:type ?type }

  # Get observable property values through observations linked to the earthquake
  OPTIONAL {
    ?observation sosa:hasFeatureOfInterest ?earthquake .
    ?observation sosa:observedProperty ?obsProp .

    # Retrieve specific properties where available
    OPTIONAL { 
      ?observation kwgr:earthquakeObservableProperty.depth ?depth .
    }
    OPTIONAL {
      ?observation kwgr:earthquakeObservableProperty.mag ?magnitude .
    }
    OPTIONAL {
      ?observation kwgr:earthquakeObservableProperty.magType ?magType .
    }
    OPTIONAL {
      ?observation kwgr:earthquakeObservableProperty.status ?status .
    }
    OPTIONAL {
      ?observation kwgr:earthquakeObservableProperty.locationSource ?locationSource .
    }
  }

  # Get geometry information
  OPTIONAL {
    ?earthquake geo:hasGeometry ?geometryDetail .
  }

  # Get temporal scope
  OPTIONAL {
    ?earthquake kwg-ont:hasTemporalScope ?temporalScope .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX kwgr: <http://stko-kwg.geog.ucsb.edu/lod/resource/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?geometry ?temporalScope ?hazardProperty ?magnitudeResult ?damageProperty ?impactResult
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  # Geographical Place attributes (Geometry)
  OPTIONAL { ?hurricane geo:hasGeometry ?geometry }

  # Temporal Data if available
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?temporalScope }

  # Hurricane-specific hazard attributes (Magnitude Observations linked to the Hazard Event)
  OPTIONAL {
    ?magObs sosa:hasFeatureOfInterest ?hurricane ;
            sosa:observedProperty ?hazardProperty .
    OPTIONAL { ?magObs sosa:hasSimpleResult ?magnitudeResult }
  }

  # Damage impact details (Impact Observations linked to the Hazard Event)
  ?impactObs sosa:hasFeatureOfInterest ?hurricane ;
             sosa:observedProperty ?damageProperty .
  OPTIONAL { ?impactObs sosa:hasSimpleResult ?impactResult }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazard ?name ?startDate ?endDate ?areaInAcres ?deaths ?cropDamage ?infraDamage ?hazardTypeLabel
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name . }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate . }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?areaInAcres . }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths . }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }

  OPTIONAL { 
    ?hazard kwgl-ont:hasHazardType ?type . 
    OPTIONAL { ?type rdfs:label ?hazardTypeLabel . }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?attrLabel ?value
WHERE {
  ?place rdf:type kwgl-ont:Place .

  VALUES ?prop { 
    kwgl-ont:percentDiabetic 
    kwgl-ont:percentObese 
    kwgl-ont:percentBelowPovertyLine 
  }

  ?place ?prop ?value .

  OPTIONAL { ?prop rdfs:label ?attrLabel }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?earthquakeEvent ?eventName ?totalCount
WHERE {
  ?earthquakeEvent rdf:type kwgl-ont:Earthquake .
  OPTIONAL { ?earthquakeEvent kwgl-ont:hasName ?eventName }
  {
    SELECT (COUNT(*) AS ?totalCount)
    WHERE { ?x rdf:type kwgl-ont:Earthquake }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?attribute
  ?attributeLabel
  ?range
  ?parentAttribute
  ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .

  OPTIONAL { ?attribute rdfs:domain kwgl-ont:Place . }
  OPTIONAL { ?attribute rdfs:range ?range . }
  OPTIONAL { ?attribute rdfs:label ?attributeLabel . }

  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel . }
  }

  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "flood") ||
    CONTAINS(LCASE(STR(?attributeLabel)), "flood")
  )
}
ORDER BY ?attribute

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?attribute ?label ?range ?parentAttribute ?parentLabel
WHERE {
  ?attribute rdf:type owl:DatatypeProperty .
  ?attribute rdfs:domain kwgl-ont:Place .
  OPTIONAL { ?attribute rdfs:label ?label }
  OPTIONAL { ?attribute rdfs:range ?range }
  OPTIONAL {
    ?attribute rdfs:subPropertyOf ?parentAttribute .
    OPTIONAL { ?parentAttribute rdfs:label ?parentLabel }
  }
  FILTER (
    CONTAINS(LCASE(STR(?attribute)), "temperature") ||
    CONTAINS(LCASE(STR(?attribute)), "cooling") ||
    CONTAINS(LCASE(STR(?attribute)), "heating") ||
    CONTAINS(LCASE(STR(?attribute)), "degree")
  )
}
ORDER BY ?label

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?earthquake ?name ?startDate ?endDate ?area ?cropDamage ?infraDamage ?deaths ?hazardType ?typeLabel
WHERE {
  ?earthquake rdf:type kwgl-ont:Earthquake .

  OPTIONAL { ?earthquake kwgl-ont:hasName ?name }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths }

  OPTIONAL { 
    ?earthquake kwgl-ont:hasHazardType ?hazardType .
    OPTIONAL { ?hazardType rdfs:label ?typeLabel }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?hazardEvent ?eventName ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths
WHERE {
  ?hazardEvent rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?hazardEvent kwgl-ont:hasName ?eventName . }
  OPTIONAL { ?hazardEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars . }
  OPTIONAL { ?hazardEvent kwgl-ont:numberOfDeaths ?numberOfDeaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?place ?hazard ?damageProperty ?damageValue
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:impactedBy ?hazard .

  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?val1 . BIND("dollarDamageOfFiresImpactingPlace" AS ?damageProperty) BIND(?val1 AS ?damageValue) 
  }
  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?val2 . BIND("dollarDamageOfFloodsImpactingPlace" AS ?damageProperty) BIND(?val2 AS ?damageValue) 
  }
  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?val3 . BIND("dollarDamageOfHurricanesImpactingPlace" AS ?damageProperty) BIND(?val3 AS ?damageValue) 
  }
  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?val4 . BIND("dollarDamageOfLandslidesImpactingPlace" AS ?damageProperty) BIND(?val4 AS ?damageValue) 
  }
  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?val5 . BIND("dollarDamageOfStormSurgesImpactingPlace" AS ?damageProperty) BIND(?val5 AS ?damageValue) 
  }
  OPTIONAL { 
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?val6 . BIND("dollarDamageOfTornadoesImpactingPlace" AS ?damageProperty) BIND(?val6 AS ?damageValue) 
  }

  OPTIONAL { 
    ?hazard kwgl-ont:damageToCropsInDollars ?val7 . BIND("damageToCropsInDollars" AS ?damageProperty) BIND(?val7 AS ?damageValue) 
  }
  OPTIONAL { 
    ?hazard kwgl-ont:damageToInfrastructureInDollars ?val8 . BIND("damageToInfrastructureInDollars" AS ?damageProperty) BIND(?val8 AS ?damageValue) 
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  ?placeName
  ?hurricaneEvent
  ?startDate
  ?endDate
  ?hazardAttribute
  ?attributeValue
  ?attributeLabel
WHERE {
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Retrieve linked Hurricane events for specific temporal data (start/end dates)
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?hurricaneEvent .
    ?hurricaneEvent rdf:type kwgl-ont:Hurricane .
    OPTIONAL { ?hurricaneEvent kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?hurricaneEvent kwgl-ont:hasEndDate ?endDate }
  }

  # Retrieve hurricane-specific hazard attributes defined on the Place (damage counts, dollar damage)
  OPTIONAL {
    ?place ?hazardAttribute ?attributeValue .
    FILTER(CONTAINS(STR(?hazardAttribute), "Hurricanes"))
    OPTIONAL { ?hazardAttribute rdfs:label ?attributeLabel }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT
  ?place
  ?event
  ?startDate
  ?endDate
  ?damageToCropsInDollars
  ?damageToInfrastructureInDollars
  ?affectedAreaInAcres
  ?numberOfDeaths
WHERE {
  ?event rdf:type kwgl-ont:Tornado .
  ?event kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT DISTINCT ?event ?place ?placeName ?startDate ?endDate ?damageCrops ?damageInfra ?areaAcres ?deaths
WHERE {
  { ?event rdf:type kwgl-ont:Hurricane }
  UNION
  { ?event rdf:type kwgl-ont:Tornado }

  ?event kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?areaAcres }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?publicationType ?typeName
WHERE {
  ?publication coresr-ont:hasPublicationType ?publicationType .
  ?publicationType coresr-ont:typeAsString ?typeName .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?state ?university ?count
WHERE {
  {
    SELECT ?state ?university (COUNT(?pub) AS ?count)
    WHERE {
      ?pub a coresr-ont:Publication .
      ?pub coresr-ont:submittedBy ?authorRole .
      ?authorRole coresr-ont:isPerformedBy ?agent .
      ?agent coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?university .
      ?university coresr-ont:locatedAt ?location .
      ?location coresr-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(?pub) AS ?c)
        WHERE {
          ?pub a coresr-ont:Publication .
          ?pub coresr-ont:submittedBy ?authorRole .
          ?authorRole coresr-ont:isPerformedBy ?agent .
          ?agent coresr-ont:associatedWith ?dept .
          ?dept coresr-ont:partOf ?college .
          ?college coresr-ont:partOf ?university .
          ?university coresr-ont:locatedAt ?location .
          ?location coresr-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER (?count = ?maxCount)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?title (COUNT(DISTINCT ?department) AS ?deptCount)
WHERE {
  {
    ?publication coresr-ont:submittedBy ?role .
    ?role a coresr-ont:Author .
  } UNION {
    ?publication coresr-ont:hasContributor ?role .
    ?role a coresr-ont:Contributor .
  }
  ?role coresr-ont:isPerformedBy ?agent .
  ?agent coresr-ont:associatedWith ?department .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title . }
}
GROUP BY ?publication ?title
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?department (COUNT(?agent) AS ?missingAgentCount)
WHERE {
  ?agent a coresr-ont:Agent .
  ?agent coresr-ont:associatedWith ?department .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?contact .
    ?contact a coresr-ont:FamilyName .
  }
}
GROUP BY ?department
ORDER BY DESC(?missingAgentCount)
LIMIT 1

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT DISTINCT ?author
WHERE {
  ?author a coresr-ont:Author .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?doiValue
WHERE {
  ?publication coresr-ont:hasIdentifier ?doi .
  ?doi coresr-ont:doiAsString ?doiValue .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?department
WHERE {
  ?department a coresr-ont:Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?submissionDate
WHERE {
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?author ?advisor
WHERE {
  ?author coresr-ont:advisedBy ?advisor .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?type ?typeName
WHERE {
  ?publication coresr-ont:hasPublicationType ?type .
  ?type coresr-ont:typeAsString ?typeName .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?agent ?department
WHERE {
  ?agent coresr-ont:associatedWith ?department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication coresr-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication
WHERE {
  ?publication a coresr-ont:Publication .

  {
    ?publication coresr-ont:submittedBy ?authorRole .
    ?agent coresr-ont:performsRole ?authorRole .
  }
  UNION
  {
    ?contributorRole coresr-ont:contributedTo ?publication .
    ?agent coresr-ont:performsRole ?contributorRole .
  }

  ?agent coresr-ont:associatedWith ?department .
}
GROUP BY ?publication
HAVING (COUNT(DISTINCT ?department) > 1)

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>

SELECT DISTINCT ?hazard ?type ?label ?timeEntity ?detailProperty ?detailValue
WHERE {
  ?hazard rdf:type ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { ?hazard skos:prefLabel ?label }

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .
    OPTIONAL { ?timeEntity time:inXSDDate ?dateValue }
    OPTIONAL { ?timeEntity time:inXSDDateTime ?dateTimeValue }
  }

  OPTIONAL { 
    ?hazard ?detailProperty ?detailValue .
    FILTER (?detailProperty != rdf:type && ?detailProperty != rdfs:label)
  }
}
ORDER BY ?type ?hazard

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX skos: <http://www.w3.org/2004/02/skos/core#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?name
WHERE {
  { ?place a kwg-ont:Region . }
  UNION
  { ?place a usgs:Feature . }

  OPTIONAL { ?place rdfs:label ?name1 }
  OPTIONAL { ?place skos:prefLabel ?name2 }
  OPTIONAL { ?place gnis:officialName ?name3 }

  BIND(COALESCE(?name1, ?name2, ?name3) AS ?name)
}
FILTER(BOUND(?name))

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?entityType ?entityLabel ?healthAttribute ?attributeValue ?regionName
WHERE {
  {
    # Health Care Facilities (Hospitals, Pharmacies, Public Health Departments)
    ?facility a ?facilityClass .
    FILTER (?facilityClass IN (kwg-ont:Hospital, kwg-ont:Pharmacy, kwg-ont:PublicHealthDepartment))

    # Retrieve Labels/Names based on class
    OPTIONAL { 
      ?facility kwg-ont:hospitalName ?entityLabel . 
      BIND("Hospital" AS ?entityType) 
    }
    OPTIONAL { 
      ?facility kwg-ont:pharmacyName ?entityLabel . 
      BIND("Pharmacy" AS ?entityType) 
    }
    OPTIONAL { 
      ?facility kwg-ont:publicHealthDepartmentName ?entityLabel . 
      BIND("Public Health Department" AS ?entityType) 
    }

    # Retrieve Health Attributes specific to each class
    OPTIONAL { ?facility kwg-ont:hospitalType ?attributeValue . BIND("Hospital Type" AS ?healthAttribute) }
    OPTIONAL { ?facility kwg-ont:traumaCareLevel ?attributeValue . BIND("Trauma Care Level" AS ?healthAttribute) }
    OPTIONAL { ?facility kwg-ont:helipadAvailability ?attributeValue . BIND("Helipad Availability" AS ?healthAttribute) }
    OPTIONAL { ?facility kwg-ont:noHospitalBeds ?attributeValue . BIND("Number of Hospital Beds" AS ?healthAttribute) }
    OPTIONAL { ?facility kwg-ont:hospitalStatus ?attributeValue . BIND("Hospital Status" AS ?healthAttribute) }
    OPTIONAL { ?facility kwg-ont:pharmacyType ?attributeValue . BIND("Pharmacy Type" AS ?healthAttribute) }

    # Link to Geographical Region (Place)
    OPTIONAL { ?facility kwg-ont:sfWithin ?region . 
               OPTIONAL { ?region rdfs:label ?regionName } 
    }
  }
  UNION
  {
    # Public Health Observations describing Regions
    ?obs a kwg-ont:PublicHealthObservation .
    ?obs sosa:hasFeatureOfInterest ?place .

    # Retrieve Observed Property (Health Concern/Attribute)
    ?obs sosa:observedProperty ?healthAttribute .

    # Retrieve Value if available
    OPTIONAL { ?obs sosa:hasResult ?attributeValue }

    # Get Place Label
    OPTIONAL { ?place rdfs:label ?regionName }

    BIND("Public Health Observation" AS ?entityType)
    BIND(?place AS ?entityLabel)
  }
}

