PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?floodEvent ?type ?property ?value ?place ?placeLabel
WHERE {
  VALUES ?type { kwg-ont:NOAACoastalFlood kwg-ont:NOAAFlood kwg-ont:NOAALakeshoreFlood }
  ?floodEvent a ?type .

  OPTIONAL { 
    ?floodEvent ?property ?value .
    FILTER (?property != rdf:type)
  }

  OPTIONAL {
    ?floodEvent kwg-ont:sfWithin ?place .
    ?place a geo:Feature .
    ?place rdfs:label ?placeLabel .
  }
}
ORDER BY ?floodEvent ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX qudt: <http://qudt.org/1.1/schema/qudt#>

SELECT DISTINCT ?place ?placeName ?fipsCode ?observedPropertyLabel ?mean ?anomaly ?rank ?numericValue
WHERE {
  ?collection a kwg-ont:ClimateDivisionObservationCollection .
  ?collection sosa:hasFeatureOfInterest ?place .

  OPTIONAL { ?place kwg-ont:climateDivisionName ?placeName }
  OPTIONAL { ?place kwg-ont:climateDivisionFIPS ?fipsCode }

  ?collection sosa:hasMember ?subCollection .
  ?subCollection sosa:hasMember ?observation .

  ?observation sosa:observedProperty ?observedProperty .
  OPTIONAL { ?observedProperty rdfs:label ?observedPropertyLabel }

  ?observation sosa:hasResult ?result .
  OPTIONAL { ?result kwg-ont:mean ?mean }
  OPTIONAL { ?result kwg-ont:anomaly ?anomaly }
  OPTIONAL { ?result kwg-ont:rank ?rank }
  OPTIONAL { 
    ?result kwg-ont:value ?quantity .
    ?quantity qudt:numericValue ?numericValue .
  }
}

