PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?tornado ?place ?timeScope ?damageType
WHERE {
  ?tornado a kwg-ont:NOAATornado .

  # Retrieve temporal extent associated with the tornado hazard
  OPTIONAL { ?tornado kwg-ont:hasTemporalScope ?timeScope . }

  # Retrieve related geographical place (Administrative Region) via spatial containment
  OPTIONAL { ?tornado kwg-ont:sfWithin ?place . }

  # Retrieve damage details via Impact Observations linked to the tornado
  OPTIONAL {
    ?obs sosa:hasFeatureOfInterest ?tornado .
    ?obs sosa:observedProperty ?damageType .
    ?damageType a kwg-ont:ImpactObservableProperty .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?hazard ?type ?timeScope ?dateTime ?property ?value
WHERE {
  ?hazard rdf:type ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?timeScope .
    OPTIONAL { ?timeScope time:inXSDDateTime ?dateTime }
  }

  OPTIONAL {
    ?hazard ?property ?value .
    FILTER ( ?property != rdf:type && ?property != rdfs:subClassOf ) 
  }
}

