PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?hazardAttribute ?relatedPlace ?damageProperty ?temporalData
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  # Hazard attributes related to geographical place (Spatial Relations/Geometry)
  OPTIONAL { 
    ?hurmane geo:hasDefaultGeometry ?geom . 
    FILTER(BOUND(?geom)) 
  }
  OPTIONAL { 
    ?hurmane kwg-ont:spatialRelation ?relatedPlace .
    FILTER(BOUND(?relatedPlace))
  }

  # Damage impact details via Impact Observations linked to the Hurricane Event
  OPTIONAL { 
    ?impactCollection sosa:hasFeatureOfInterest ?hurricane .
    ?impactCollection a kwg-ont:ImpactObservationCollection .

    # Temporal data if available
    OPTIONAL { ?impactCollection sosa:phenomenonTime ?temporalData . }

    # Damage properties observed in the impact collection members
    OPTIONAL { 
      ?impactCollection sosa:hasMember ?observation .
      ?observation sosa:observedProperty ?damageProperty .
    }
  }

  # General attributes of the hurricane event (e.g. IDs, names if defined)
  OPTIONAL { 
    ?hurmane ?hazardAttribute ?attrValue .
    FILTER( !?hurmane = kwg-ont:NOAAHurricane ) 
    FILTER( ?hazardAttribute != a )
  }
}
ORDER BY ?hurricane ?damageProperty

