PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?state ?uni (COUNT(?pub) AS ?count)
WHERE {
  {
    SELECT ?uni ?st (COUNT(DISTINCT ?pub) AS ?c)
    WHERE {
      ?pub coresr-ont:submittedBy ?author .
      ?agent coresr-ont:performsRole ?author .
      ?agent coresr-ont:associatedWith ?dept .
      ?dept coresr-ont:partOf ?college .
      ?college coresr-ont:partOf ?uni .
      ?uni coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?st .
    }
    GROUP BY ?uni ?st
  }

  {
    SELECT ?s (MAX(?cnt) AS ?max_cnt)
    WHERE {
      {
        SELECT ?u ?st (COUNT(DISTINCT ?p) AS ?c)
        WHERE {
          ?p coresr-ont:submittedBy ?a .
          ?ag coresr-ont:performsRole ?a .
          ?ag coresr-ont:associatedWith ?d .
          ?d coresr-ont:partOf ?col .
          ?col coresr-ont:partOf ?u .
          ?u coresr-ont:locatedAt ?l .
          ?l coresr-ont:atState ?st .
        }
        GROUP BY ?u ?st
      }
    }
    GROUP BY ?s
  }

  FILTER (?st = ?s && ?c = ?max_cnt)
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?pub (COUNT(DISTINCT ?dept) AS ?departmentCount) WHERE {
  ?pub a coresr-ont:Publication .

  {
    ?pub coresr-ont:submittedBy ?person .
    ?person coresr-ont:associatedWith ?dept .
  }
  UNION
  {
    ?contributor coresr-ont:contributedTo ?pub .
    ?contributor coresr-ont:associatedWith ?dept .
  }
} GROUP BY ?pub HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?dept (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent coresr-ont:associatedWith ?dept .
  FILTER NOT EXISTS {
    ?agent coresr-ont:hasContactInformation ?ci .
    ?ci a coresr-ont:FamilyName .
  }
}
GROUP BY ?dept
ORDER BY DESC(?missingCount)

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
