  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?placeName ?damageAmount ?hurricaneCount ?startDate ?endDate
WHERE {
  ?place rdf:type kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName . }

  # Hurricane-specific hazard attributes on Place (Damage and Counts)
  # These properties aggregate data, potentially including sub-properties for specific years
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?damageAmount . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount . }

  # Temporal data from linked Hurricane Events
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?event .
    ?event rdf:type kwgl-ont:Hurricane .

    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?event ?placeName ?startDate ?endDate ?damageCrops ?damageInfrastructure ?affectedArea ?deaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  ?event kwgl-ont:hasHazardType kwglr:tornado .

  ?event kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>

SELECT DISTINCT ?place ?placeName ?hazard ?startDate ?endDate ?damageCrops ?damageInfra ?affectedArea ?hazardType
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType ?hazardType .

  # Filter for storm-specific hazards based on URI string content
  FILTER (
    CONTAINS(STR(?hazardType), "hurricane") ||
    CONTAINS(STR(?hazardType), "tropical") ||
    CONTAINS(STR(?hazardType), "storm") ||
    CONTAINS(STR(?hazardType), "blizzard") ||
    CONTAINS(STR(?hazardType), "iceStorm") ||
    CONTAINS(STR(?hazardType), "winter") ||
    CONTAINS(STR(?hazardType), "thunder") ||
    CONTAINS(STR(?hazardType), "dust")
  )

  ?hazard kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?author WHERE {
  ?author a coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?doi
WHERE {
  ?publication a coress-ont:Publication .
  OPTIONAL { ?publication coress-ont:hasDOI ?doi }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?agent ?firstName ?lastName ?department
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?department .
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName }
  OPTIONAL { ?agent coress-ont:hasFamilyName ?lastName }
