PREFIX : <http://example.org/core_scholar_shallow/>
PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication ;
               coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?city ?college WHERE {
  ?college a coress-ont:College .
  ?college coress-ont:collegeOf ?university .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?publicationCount WHERE {
  # Calculate publication count for each university
  {
    SELECT ?university (COUNT(?pub) AS ?publicationCount)
    WHERE {
      ?pub a coress-ont:Publication ;
           coress-ont:submittedBy ?author .
      ?author a coress-ont:Author ;
              coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
    }
    GROUP BY ?university
  }

  # Retrieve state for the university
  ?university a coress-ont:University ;
              coress-ont:atState ?state .

  # Filter to keep only universities with the maximum publication count per state
  FILTER NOT EXISTS {
    ?otherUni a coress-ont:University ;
              coress-ont:atState ?state .
    FILTER(?otherUni != ?university)

    {
      SELECT (COUNT(?p2) AS ?cnt)
      WHERE {
        ?p2 a coress-ont:Publication ;
             coress-ont:submittedBy ?a2 .
        ?a2 a coress-ont:Author ;
           coress-ont:isPerformedBy ?ag2 .
        ?ag2 coress-ont:worksInDepartment ?d2 .
        ?d2 coress-ont:departmentOf ?c2 .
        ?c2 coress-ont:collegeOf ?otherUni .
      }
    }
    FILTER(?cnt > ?publicationCount)
  }
}
ORDER BY ?state DESC(?publicationCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?dept (COUNT(?agent) AS ?count)
WHERE {
  ?dept a coress-ont:Department .
  ?dept coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fn }
}
GROUP BY ?dept
ORDER BY DESC(?count)
LIMIT 1

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?timeValue ?detailProp ?detailVal
WHERE {
  ?hazard rdf:type ?HazardType .
  ?HazardType rdfs:subClassOf* kwg-ont:Hazard .

  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?timeNode .
    OPTIONAL { ?timeNode time:inXSDDateTime ?timeValue }
  }

  OPTIONAL { 
    ?hazard ?detailProp ?detailVal .
    FILTER(?detailProp != rdf:type && ?detailProp != rdfs:subClassOf)
  }
}
ORDER BY ?hazard ?timeValue

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>

SELECT DISTINCT ?place ?name
WHERE {
  { ?place a kwg-ont:Region } UNION
  { ?place a usgs:BuiltUpArea } UNION
  { ?place a usgs:Terrain } UNION
  { ?place a usgs:SurfaceWater }
  OPTIONAL { ?place rdfs:label ?name }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?place ?healthAttribute
WHERE {
  ?obs sosa:hasFeatureOfInterest ?place .
  ?obs sosa:observedProperty ?healthAttribute .
  ?place a geo:Feature .
  { ?healthAttribute rdfs:subClassOf* kwg-ont:PublicHealthObservableProperty . }
  UNION
  { ?healthAttribute rdfs:subClassOf* kwg-ont:VulnerabilityObservableProperty . }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard ?totalCount
WHERE {
  ?hazard rdfs:subClassOf* kwg-ont:Earthquake .
  {
    SELECT (COUNT(DISTINCT ?x) AS ?totalCount)
    WHERE { ?x rdfs:subClassOf* kwg-ont:Earthquake }
  }
}
ORDER BY ?hazard

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?attributeClass (COUNT(?all) AS ?totalCount)
WHERE {
  { SELECT (COUNT(DISTINCT ?attr) AS ?all) WHERE { ?attr rdfs:subClassOf* kwg-ont:TornadoMagnitudeObservationCollection } }
  ?attributeClass rdfs:subClassOf* kwg-ont:TornadoMagnitudeObservationCollection .
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT DISTINCT ?floodType ?property ?value ?place ?placeLabel
WHERE {
  { ?floodType rdfs:subClassOf* kwg-ont:NOAAFlood }
  UNION
  { ?floodType rdfs:subClassOf* kwg-ont:NOAACoastalFlood }
  UNION
  { ?floodType rdfs:subClassOf* kwg-ont:NOAALakeshoreFlood }

  OPTIONAL { ?floodType ?property ?value . FILTER(?property != rdf:type && ?property != rdfs:subClassOf) }

  OPTIONAL { ?floodType kwg-ont:spatialRelation ?place . }
  OPTIONAL { ?place rdfs:label ?placeLabel . }
}
ORDER BY ?floodType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?climateAttribute ?label
WHERE {
  ?climateAttribute rdfs:subClassOf* kwg-ont:ClimateObservableProperty .
  OPTIONAL { ?climateAttribute rdfs:label ?label }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?earthquakeType ?superType ?property ?value
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  OPTIONAL { ?earthquakeType rdfs:subClassOf ?superType . }
  OPTIONAL { ?earthquakeType ?property ?value . }
}
ORDER BY ?earthquakeType ?property

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?place ?damageProperty ?temporalScope ?phenomenonTime
WHERE {
  ?hurricane a kwg-ont:NOAAHurricane .

  # Retrieve geographical place related to the hurricane (based on schema restriction Hazard ⊑ spatialRelation AdministrativeRegion)
  ?hurricane kwg-ont:spatialRelation ?place .

  # Retrieve damage impact details via ImpactObservationCollection linked to the hazard event
  OPTIONAL {
    ?impactCollection sosa:hasFeatureOfInterest ?hurricane .
    ?impactCollection sosa:observedProperty ?damageProperty .
  }

  # Retrieve temporal data for the hurricane event itself
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?temporalScope . }

  # Retrieve temporal data for the impact observations if available
  OPTIONAL { ?impactCollection sosa:phenomenonTime ?phenomenonTime . }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?hazard ?type ?name ?timeValue
WHERE {
  ?hazard a kwg-ont:Hazard .

  # Get the specific type of hazard
  ?hazard rdf:type ?type .

  # Attempt to retrieve name details from common properties or rdfs:label
  OPTIONAL {
    BIND(
      COALESCE(?disasterName, ?fireName, ?incidentName, ?hazardLabel) AS ?name
    )
  }
  OPTIONAL { ?hazard kwg-ont:hasDisasterName ?disasterName }
  OPTIONAL { ?hazard kwg-ont:hasFireName ?fireName }
  OPTIONAL { ?hazard kwg-ont:hasIncidentName ?incidentName }
  OPTIONAL { ?hazard rdfs:label ?hazardLabel }

  # Retrieve time from direct temporal scope property (e.g., Drought, Earthquake, Smoke)
  OPTIONAL {
    ?hazard kwg-ont:hasTemporalScope ?timeEntity .
    ?timeEntity time:inXSDDateTime ?timeValueDirect .
  }

  # Retrieve time from associated Observation Collections if direct property is absent (e.g., NOAA Hazards)
  OPTIONAL {
    ?obsCollection sosa:hasFeatureOfInterest ?hazard .
    ?obsCollection sosa:phenomenonTime ?obsTimeEntity .
    ?obsTimeEntity time:inXSDDateTime ?timeValueObs .
  }

  # Use the direct time if available, otherwise use observation collection time
  BIND(COALESCE(?timeValueDirect, ?timeValueObs) AS ?timeValue)
}

PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>

SELECT ?place ?name
WHERE {
  {
    ?place a kwg-ont:Hospital ;
           kwg-ont:hospitalName ?name .
  }
  UNION
  {
    ?place a kwg-ont:Pharmacy ;
           kwg-ont:pharmacyName ?name .
  }
  UNION
  {
    ?place a kwg-ont:PublicHealthDepartment ;
           kwg-ont:publicHealthDepartmentName ?name .
  }
  UNION
  {
    ?place a kwg-ont:FederalJudicalDistrict ;
           kwg-ont:hasName ?name .
  }
  UNION
  {
    ?place a kwg-ont:RoadSegment ;
           kwg-ont:hasRoadName ?name .
  }
  UNION
  {
    ?place a kwg-ont:AirQualitySite ;
           (kwg-ont:cbsaName | kwg-ont:siteName) ?name .
  }
  UNION
  {
    ?place a kwg-ont:USClimateDivision ;
           kwg-ont:climateDivisionName ?name .
  }
  UNION
  {
    ?place a geo:Feature ;
           rdfs:label ?name .
  }
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?earthquake ?totalCount WHERE {
  ?earthquake a kwg-ont:Earthquake .
  {
    SELECT (COUNT(DISTINCT ?e) AS ?totalCount) WHERE { 
      ?e a kwg-ont:Earthquake .
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?flood ?hazardType ?geometry ?timeScope ?relatedPlace ?placeType
WHERE {
  VALUES ?hazardType { kwg-ont:NOAACoastalFlood kwg-ont:NOAAFlashFlood kwg-ont:NOAALakeshoreFlood }

  ?flood rdf:type ?hazardType .

  # Retrieve available hazard attributes (Geometry, Temporal Scope) as defined in the schema for Features/Hazards
  OPTIONAL { ?flood geo:hasDefaultGeometry ?geometry . }
  OPTIONAL { ?flood kwg-ont:hasGeometry ?geometry . }
  OPTIONAL { ?flood kwg-ont:hasTemporalScope ?timeScope . }

  # Retrieve related geographical places based on schema-defined spatial relations
  OPTIONAL {
    {
      ?flood kwg-ont:sfWithin ?relatedPlace .
      ?relatedPlace rdf:type ?placeType .
    } UNION {
      ?flood kwg-ont:spatialRelation ?relatedPlace .
      ?relatedPlace rdf:type ?placeType .
    }
  }

  # Filter places to specific geographical types defined in the schema context
  FILTER(?placeType IN (kwg-ont:S2Cell, kwg-ont:AdministrativeRegion_3, geo:Feature))
}

PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?earthquake ?type ?geometry ?timeScope ?observedProperty
WHERE {
  ?earthquake rdf:type kwg-ont:Earthquake .
  ?earthquake rdf:type ?type .
  OPTIONAL { ?earthquake geo:hasDefaultGeometry ?geometry }
  OPTIONAL { ?earthquake kwg-ont:hasTemporalScope ?timeScope }
  OPTIONAL {
    ?collection sosa:hasFeatureOfInterest ?earthquake .
    ?collection sosa:hasMember ?obs .
    ?obs sosa:observedProperty ?observedProperty .
  }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
