PREFIX : <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?department WHERE {
  ?department rdf:type :Department .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?submissionDate
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:dateOfSubmission ?submissionDate .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?publication ?title ?pubType ?typeLabel
WHERE {
  ?publication a coresr-ont:Publication .
  ?publication coresr-ont:hasPublicationType ?pubType .
  OPTIONAL { ?publication coresr-ont:hasTitle ?title }
  OPTIONAL { ?pubType coresr-ont:typeAsString ?typeLabel }
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>

SELECT ?fieldOfStudy ?publication
WHERE {
  ?fieldOfStudy a coresr-ont:FieldOfStudy ;
                coresr-ont:isFieldOfStudyOf ?publication .
}

PREFIX coresr-ont: <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?state ?univ ?pubCount
WHERE {
  {
    SELECT ?state ?univ (COUNT(DISTINCT ?pub) AS ?pubCount)
    WHERE {
      ?univ a coresr-ont:University .
      ?univ coresr-ont:locatedAt ?loc .
      ?loc coresr-ont:atState ?state .

      ?dept (coresr-ont:partOf)+ ?univ .

      ?agent coresr-ont:associatedWith ?dept .

      ?role coresr-ont:isPerformedBy ?agent .

      { ?pub coresr-ont:submittedBy ?role. } UNION { ?pub coresr-ont:hasContributor ?role. }
    }
    GROUP BY ?state ?univ
  }

  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?u (COUNT(DISTINCT ?p) AS ?c)
        WHERE {
          ?u a coresr-ont:University .
          ?u coresr-ont:locatedAt ?l .
          ?l coresr-ont:atState ?state .

          ?d (coresr-ont:partOf)+ ?u .
          ?a coresr-ont:associatedWith ?d .
          ?r coresr-ont:isPerformedBy ?a .

          { ?p coresr-ont:submittedBy ?r. } UNION { ?p coresr-ont:hasContributor ?r. }
        }
        GROUP BY ?state ?u
      }
    }
    GROUP BY ?state
  }

  FILTER (?pubCount = ?maxCount)
}
ORDER BY ?state DESC(?pubCount)

PREFIX : <http://example.org/core_scholar_rich/>

SELECT DISTINCT ?author WHERE {
  ?author a :Author ;
          :advisedBy ?advisor ;
          :submits ?publication .
  ?publication :associatedFieldOfStudy ?field .
}

PREFIX : <http://example.org/core_scholar_rich/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department (COUNT(?agent) AS ?missingCount)
WHERE {
  ?dept a :Department .
  ?dept :hasAssociatedAgent ?agent .

  FILTER NOT EXISTS {
    ?agent :hasContactInformation [ rdf:type :FamilyName ] .
  }
}
GROUP BY ?dept
ORDER BY DESC(?missingCount)

