PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?placeName ?tornadoAttribute ?value (COUNT(?tornadoAttribute) AS ?totalCount)
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  {
    ?place kwgl-ont:numberOfTornadoesImpactingPlace ?value ;
           FILTER(!isBlank(?value))
    BIND("numberOfTornadoesImpactingPlace" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?value ;
           FILTER(!isBlank(?value))
    BIND("dollarDamageOfTornadoesImpactingPlace" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2018 ?value ;
           FILTER(!isBlank(?value))
    BIND("numberOfTornadoesImpactingPlace2018" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2019 ?value ;
           FILTER(!isBlank(?value))
    BIND("numberOfTornadoesImpactingPlace2019" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2020 ?value ;
           FILTER(!isBlank(?value))
    BIND("numberOfTornadoesImpactingPlace2020" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2021 ?value ;
           FILTER(!isBlank(?value))
    BIND("numberOfTornadoesImpactingPlace2021" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:numberOfTornadoesImpactingPlace2022 ?value ;
           FILTER(!isBlank(?value))
    BIND("numberOfTornadoesImpactingPlace2022" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?value ;
           FILTER(!isBlank(?value))
    BIND("dollarDamageOfTornadoesImpactingPlace2018" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?value ;
           FILTER(!isBlank(?value))
    BIND("dollarDamageOfTornadoesImpactingPlace2019" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?value ;
           FILTER(!isBlank(?value))
    BIND("dollarDamageOfTornadoesImpactingPlace2020" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?value ;
           FILTER(!isBlank(?value))
    BIND("dollarDamageOfTornadoesImpactingPlace2021" AS ?tornadoAttribute)
  } UNION {
    ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?value ;
           FILTER(!isBlank(?value))
    BIND("dollarDamageOfTornadoesImpactingPlace2022" AS ?tornadoAttribute)
  }
}
GROUP BY ?placeName ?tornadoAttribute ?value

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?place 
       # Hurricane Attributes (Generic & Years 2018-2022)
       ?hurricaneCount ?hurricaneDamage ?hurricaneCount_2018 ?hurricaneDamage_2018 ?hurricaneCount_2019 ?hurricaneDamage_2019 
       ?hurricaneCount_2020 ?hurricaneDamage_2020 ?hurricaneCount_2021 ?hurricaneDamage_2021 ?hurricaneCount_2022 ?hurricaneDamage_2022
       # Tornado Attributes (Generic & Years 2018-2022)
       ?tornadoCount ?tornadoDamage ?tornadoCount_2018 ?tornadoDamage_2018 ?tornadoCount_2019 ?tornadoDamage_2019 
       ?tornadoCount_2020 ?tornadoDamage_2020 ?tornadoCount_2021 ?tornadoDamage_2021 ?tornadoCount_2022 ?tornadoDamage_2022
       # Storm Surge Attributes (Generic & Years 2018-2022)
       ?surgeCount ?surgeDamage ?surgeCount_2018 ?surgeDamage_2018 ?surgeCount_2019 ?surgeDamage_2019 
       ?surgeCount_2020 ?surgeDamage_2020 ?surgeCount_2021 ?surgeDamage_2021 ?surgeCount_2022 ?surgeDamage_2022
WHERE {
  ?place a kwgl-ont:Place .

  # Hurricane Optional Properties
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?hurricaneCount_2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?hurricaneDamage_2018 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?hurricaneCount_2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?hurricaneDamage_2019 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?hurricaneCount_2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?hurricaneDamage_2020 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?hurricaneCount_2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?hurricaneDamage_2021 }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?hurricaneCount_2022 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?hurricaneDamage_2022 }

  # Tornado Optional Properties
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace ?tornadoCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2018 ?tornadoCount_2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?tornadoDamage_2018 }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2019 ?tornadoCount_2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?tornadoDamage_2019 }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2020 ?tornadoCount_2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?tornadoDamage_2020 }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2021 ?tornadoCount_2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?tornadoDamage_2021 }
  OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2022 ?tornadoCount_2022 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?tornadoDamage_2022 }

  # Storm Surge Optional Properties
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?surgeCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?surgeDamage }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2018 ?surgeCount_2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2018 ?surgeDamage_2018 }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2019 ?surgeCount_2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2019 ?surgeDamage_2019 }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2020 ?surgeCount_2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2020 ?surgeDamage_2020 }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2021 ?surgeCount_2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2021 ?surgeDamage_2021 }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace2022 ?surgeCount_2022 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2022 ?surgeDamage_2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?placeName 
       ?numberOfFloodsImpactingPlace ?numberOfFloodsImpactingPlace2018 ?numberOfFloodsImpactingPlace2019 
       ?numberOfFloodsImpactingPlace2020 ?numberOfFloodsImpactingPlace2021 ?numberOfFloodsImpactingPlace2022
       ?dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace2018 
       ?dollarDamageOfFloodsImpactingPlace2019 ?dollarDamageOfFloodsImpactingPlace2020 
       ?dollarDamageOfFloodsImpactingPlace2021 ?dollarDamageOfFloodsImpactingPlace2022
WHERE {
  ?place a kwgl-ont:Place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?numberOfFloodsImpactingPlace }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2018 ?numberOfFloodsImpactingPlace2018 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2019 ?numberOfFloodsImpactingPlace2019 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2020 ?numberOfFloodsImpactingPlace2020 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2021 ?numberOfFloodsImpactingPlace2021 }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace2022 ?numberOfFloodsImpactingPlace2022 }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageOfFloodsImpactingPlace }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2018 ?dollarDamageOfFloodsImpactingPlace2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2019 ?dollarDamageOfFloodsImpactingPlace2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2020 ?dollarDamageOfFloodsImpactingPlace2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2021 ?dollarDamageOfFloodsImpactingPlace2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace2022 ?dollarDamageOfFloodsImpactingPlace2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name 
       (GROUP_CONCAT(DISTINCT ?tempAttr; SEPARATOR=", ") AS ?temperatureAttributes)
       (GROUP_CONCAT(DISTINCT ?coolingAttr; SEPARATOR=", ") AS ?coolingDegreeDays)
       (GROUP_CONCAT(DISTINCT ?heatingAttr; SEPARATOR=", ") AS ?heatingDegreeDays)
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }

  # Temperature attributes for all months
  OPTIONAL { 
    VALUES ?monthPred { 
      kwgl-ont:averageMonthlyTemperatureInCelsius kwgl-ont:minimumMonthlyTemperatureInCelsius kwgl-ont:maximumMonthlyTemperatureInCelsius
      kwgl-ont:averageMonthlyTemperatureInCelsiusJan2021 kwgl-ont:averageMonthlyTemperatureInCelsiusFeb2021 kwgl-ont:averageMonthlyTemperatureInCelsiusMar2021
      kwgl-ont:averageMonthlyTemperatureInCelsiusApr2021 kwgl-ont:averageMonthlyTemperatureInCelsiusMay2021 kwgl-ont:averageMonthlyTemperatureInCelsiusJun2021
      kwgl-ont:averageMonthlyTemperatureInCelsiusJul2021 kwgl-ont:averageMonthlyTemperatureInCelsiusAug2021 kwgl-ont:averageMonthlyTemperatureInCelsiusSep2021
      kwgl-ont:averageMonthlyTemperatureInCelsiusOct2021 kwgl-ont:averageMonthlyTemperatureInCelsiusNov2021 kwgl-ont:averageMonthlyTemperatureInCelsiusDec2021
    }
    ?place ?monthPred ?tempVal .
    BIND(CONCAT(STR(?monthPred), "=", STR(?tempVal)) AS ?tempAttr)
  }

  # Cooling Degree Days attributes
  OPTIONAL { 
    VALUES ?coolingPred {
      kwgl-ont:averageCoolingDegreeDaysPerMonth kwgl-ont:averageCoolingDegreeDaysPerMonthJan2021 kwgl-ont:averageCoolingDegreeDaysPerMonthFeb2021
      kwgl-ont:averageCoolingDegreeDaysPerMonthMar2021 kwgl-ont:averageCoolingDegreeDaysPerMonthApr2021 kwgl-ont:averageCoolingDegreeDaysPerMonthMay2021
      kwgl-ont:averageCoolingDegreeDaysPerMonthJun2021 kwgl-ont:averageCoolingDegreeDaysPerMonthJul2021 kwgl-ont:averageCoolingDegreeDaysPerMonthAug2021
      kwgl-ont:averageCoolingDegreeDaysPerMonthSep2021 kwgl-ont:averageCoolingDegreeDaysPerMonthOct2021 kwgl-ont:averageCoolingDegreeDaysPerMonthNov2021
      kwgl-ont:averageCoolingDegreeDaysPerMonthDec2021
    }
    ?place ?coolingPred ?coolVal .
    BIND(CONCAT(STR(?coolingPred), "=", STR(?coolVal)) AS ?coolingAttr)
  }

  # Heating Degree Days attributes
  OPTIONAL { 
    VALUES ?heatingPred {
      kwgl-ont:averageHeatingDegreeDaysPerMonth kwgl-ont:averageHeatingDegreeDaysPerMonthJan2021 kwgl-ont:averageHeatingDegreeDaysPerMonthFeb2021
      kwgl-ont:averageHeatingDegreeDaysPerMonthMar2021 kwgl-ont:averageHeatingDegreeDaysPerMonthApr2021 kwgl-ont:averageHeatingDegreeDaysPerMonthMay2021
      kwgl-ont:averageHeatingDegreeDaysPerMonthJun2021 kwgl-ont:averageHeatingDegreeDaysPerMonthJul2021 kwgl-ont:averageHeatingDegreeDaysPerMonthAug2021
      kwgl-ont:averageHeatingDegreeDaysPerMonthSep2021 kwgl-ont:averageHeatingDegreeDaysPerMonthOct2021 kwgl-ont:averageHeatingDegreeDaysPerMonthNov2021
      kwgl-ont:averageHeatingDegreeDaysPerMonthDec2021
    }
    ?place ?heatingPred ?heatVal .
    BIND(CONCAT(STR(?heatingPred), "=", STR(?heatVal)) AS ?heatingAttr)
  }
}
GROUP BY ?place ?name

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?name ?startDate ?endDate ?numberOfDeaths ?damageToInfrastructureInDollars ?damageToCropsInDollars ?affectedAreaInAcres ?hazardType
WHERE {
  ?earthquake a kwgl-ont:HazardEvent .
  ?earthquake kwgl-ont:hasHazardType ?hazardType .
  FILTER(?hazardType = kwglr:earthquake) .

  OPTIONAL { ?earthquake kwgl-ont:hasName ?name }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?event ?name ?hazardType ?deaths ?infrastructureDamage ?cropDamage ?affectedArea
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:hasName ?name }
  OPTIONAL { ?event kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?damageToInfrastructureInDollars ?damageToCropsInDollars ?affectedAreaInAcres ?numberOfDeaths
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?placeName ?startDate ?endDate ?hurricaneCount ?hurricaneDamage
       ?count2018 ?damage2018 ?count2019 ?damage2019
       ?count2020 ?damage2020 ?count2021 ?damage2021
       ?count2022 ?damage2022
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .
  ?place kwgl-ont:impactedBy ?hurricaneEvent .
  ?hurricaneEvent a kwgl-ont:Hurricane .

  # Temporal data from the Hazard Event
  OPTIONAL { ?hurricaneEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hurricaneEvent kwgl-ont:hasEndDate ?endDate }

  # Hurricane-specific hazard attributes on Place (Generic)
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }

  # Hurricane-specific hazard attributes on Place (Year-specific per schema)
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?count2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damage2018 }

  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?count2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?damage2019 }

  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?count2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?damage2020 }

  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?count2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?damage2021 }

  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?count2022 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?damage2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT DISTINCT ?place ?placeName ?hazard ?startDate ?endDate 
       ?dollarDamageTornadoes ?numberOfTornadoes ?affectedAreaInAcres
WHERE {
    ?hazard a kwgl-ont:Tornado .
    ?hazard kwgl-ont:hasImpacted ?place .

    OPTIONAL { ?place kwgl-ont:hasName ?placeName }
    OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

    # Tornado-specific damage properties on Places (general and year-specific)
    OPTIONAL { 
        ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageTornadoes . 
    }
    OPTIONAL { 
        ?place kwgl-ont:numberOfTornadoesImpactingPlace ?numberOfTornadoes . 
    }

    # Year-specific tornado damage on places
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2018 ?dmg2018 . }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2019 ?dmg2019 . }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2020 ?dmg2020 . }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2021 ?dmg2021 . }
    OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace2022 ?dmg2022 . }

    OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2018 ?cnt2018 . }
    OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2019 ?cnt2019 . }
    OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2020 ?cnt2020 . }
    OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2021 ?cnt2021 . }
    OPTIONAL { ?place kwgl-ont:numberOfTornadoesImpactingPlace2022 ?cnt2022 . }

    # Tornado hazard event damage properties
    OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres . }
    OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
    OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazardName ?placeName ?startDate ?endDate ?damageToInfrastructure ?damageToCrops ?numberOfDeaths ?affectedArea 
WHERE {
  ?hazard a kwgl-ont:Hurricane .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName }

  ?hazard kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
}

UNION

SELECT ?placeName ?yearDamage ?damageType 
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  FILTER EXISTS {
    VALUES ?prop {
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021
      kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2018
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2019
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2020
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2021
      kwgl-ont:dollarDamageOfStormSurgesImpactingPlace2022
    }
    ?place ?prop ?yearDamage .
  }

  BIND(REPLACE(STR(?prop), ".*dollarDamageOf", "") AS ?damageType)
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>

SELECT DISTINCT ?hazard ?type ?label ?timeValue ?property ?value
WHERE {
  # Identify all instances of Hazard and its subclasses
  ?hazard rdf:type ?type .
  ?type rdfs:subClassOf* kwg-ont:Hazard .

  # Retrieve label for identification details
  OPTIONAL { ?hazard rdfs:label ?label . }

  # Retrieve temporal information when they happened
  OPTIONAL { 
    ?hazard kwg-ont:hasTemporalScope ?tempEntity .
    # Try to get datetime directly or via start of interval
    { ?tempEntity time:inXSDDateTime ?timeValue }
    UNION
    { ?tempEntity time:hasBeginning ?start . ?start time:inXSDDateTime ?timeValue }
  }

  # Retrieve all other available details (properties and values)
  OPTIONAL { 
    ?hazard ?property ?value . 
    FILTER(?property != rdf:type && ?property != kwg-ont:hasTemporalScope)
  }
}
ORDER BY ?label ?timeValue

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX gnis: <http://gnis-ld.org/lod/gnis/ontology/>
PREFIX usgs: <http://gnis-ld.org/lod/usgs/ontology/>

SELECT DISTINCT ?place ?name WHERE {
  {
    ?place rdf:type gnis:State .
    OPTIONAL { ?place gnis:stateName ?name }
  }
  UNION
  {
    ?place rdf:type gnis:County .
    OPTIONAL { ?place gnis:countyName ?name }
  }
  UNION
  {
    ?place rdf:type usgs:Feature .
    OPTIONAL { ?place rdfs:label ?name }
    OPTIONAL { ?place gnis:officialName ?name }
  }
}
ORDER BY ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?earthquakeType ?totalCount
WHERE {
  ?earthquakeType rdfs:subClassOf* kwg-ont:Earthquake .
  {
    SELECT (COUNT(DISTINCT ?h) AS ?totalCount)
    WHERE { 
      ?h rdfs:subClassOf* kwg-ont:Earthquake .
    }
  }
}

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?floodEvent ?type ?place ?property ?value
WHERE {
  {
    ?floodEvent rdf:type ?type .
    ?type rdfs:subClassOf* kwg-ont:NOAAFlood .
  } UNION {
    ?floodEvent rdf:type ?type .
    ?type rdfs:subClassOf* kwg-ont:NOAACoastalFlood .
  } UNION {
    ?floodEvent rdf:type ?type .
    ?type rdfs:subClassOf* kwg-ont:NOAALakeshoreFlood .
  }

  OPTIONAL { ?floodEvent kwg-ont:spatialRelation ?place . }

  OPTIONAL { 
    ?floodEvent ?property ?value .
    FILTER(?property != rdf:type)
  }
}
ORDER BY ?floodEvent ?place

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?climateAttribute ?obsClass ?placeType
WHERE {
  ?climateAttribute rdfs:subClassOf* kwg-ont:ClimateObservableProperty .

  OPTIONAL {
    ?obsClass sosa:observedProperty ?climateAttribute .
    ?obsClass sosa:hasFeatureOfInterest ?placeType .
  }
}
ORDER BY ?climateAttribute

PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX time: <http://www.w3.org/2006/time#>

SELECT DISTINCT ?earthquake ?type ?property ?value
WHERE {
  VALUES ?earthquake { kwg-ont:Earthquake }

  # Retrieve Types (Superclasses)
  OPTIONAL { ?earthquake rdfs:subClassOf ?type . }

  # Retrieve Details (Any other properties associated with the Earthquake class in schema)
  OPTIONAL { ?earthquake ?property ?value . }
}
ORDER BY ?type ?property

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT DISTINCT ?hurricane ?geometry ?regionName ?temporalScope ?obsProperty ?impactResult
WHERE {
  # Identify Hurricane Hazards (instances of NOAAHurricane)
  ?hurricane rdf:type kwg-ont:NOAAHurricane .

  # Geographical Place: Geometry associated with the hazard
  OPTIONAL { ?hurricane geo:hasGeometry ?geometry . }

  # Geographical Place: Spatial relation to Administrative Regions for place names
  OPTIONAL { 
    ?hurricane kwg-ont:spatialRelation ?region .
    ?region rdfs:label ?regionName . 
  }

  # Temporal Data: Scope of the hazard event
  OPTIONAL { ?hurricane kwg-ont:hasTemporalScope ?timeEntity . }
  OPTIONAL { 
    ?timeEntity time:inXSDDateTime ?temporalScope . 
  }

  # Hazard Attributes and Damage Impact Details via Observations linked to the Hurricane
  OPTIONAL { 
    ?observation sosa:hasFeatureOfInterest ?hurricane .

    # Retrieve Observed Properties (e.g., Wind Speed, Category)
    OPTIONAL { ?observation sosa:observedProperty ?obsProperty . }

    # Retrieve Results of Observations (Impact values like damage costs, casualties)
    OPTIONAL { ?observation sosa:hasSimpleResult ?impactResult . }
  }
}
ORDER BY ?hurricane ?obsProperty

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX geo: <http://www.opengis.net/ont/geosparql#>
PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX time: <http://www.w3.org/2006/time#>
PREFIX kwg-ont: <http://stko-kwg.geog.ucsb.edu/lod/ontology/>

SELECT DISTINCT ?hazard ?timeScope ?geometry ?region ?damageType ?resultValue
WHERE {
  ?hazard rdf:type kwg-ont:NOAATornado .

  # Retrieve Temporal Extent of the Tornado Hazard
  ?hazard kwg-ont:hasTemporalScope ?timeScope .

  # Retrieve Geographical Place (Geometry or Administrative Region)
  OPTIONAL { ?hazard geo:hasGeometry ?geometry }
  OPTIONAL { ?hazard kwg-ont:spatialRelation ?region }

  # Retrieve Damage Details via Impact Observations linked to the Hazard
  OPTIONAL {
    ?obs sosa:hasFeatureOfInterest ?hazard .
    ?obs rdf:type kwg-ont:ImpactObservation .
    ?obs sosa:observedProperty ?damageType .
    ?damageType rdfs:subClassOf* kwg-ont:ImpactObservableProperty .
    OPTIONAL { ?obs sosa:hasSimpleResult ?resultValue }
  }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?author ?firstName ?familyName
WHERE {
  ?author rdf:type coress-ont:Author .
  OPTIONAL { ?agent coress-ont:performsRole ?author }
  OPTIONAL { ?agent coress-ont:hasFirstName ?firstName }
  OPTIONAL { ?agent coress-ont:hasFamilyName ?familyName }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?department
WHERE {
  ?department a coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?agent ?department
WHERE {
  ?agent coress-ont:worksInDepartment ?department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT DISTINCT ?city ?university ?college
WHERE {
  ?university a coress-ont:University ;
              coress-ont:atCity ?city ;
              coress-ont:hasCollege ?college .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?univ ?count
WHERE {
  {
    SELECT ?state ?univ (COUNT(DISTINCT ?pub) AS ?count)
    WHERE {
      ?pub a coress-ont:Publication .
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:isPerformedBy ?agent .
      ?agent coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?univ .
      ?univ coress-ont:atState ?state .
    }
    GROUP BY ?state ?univ
  }
  {
    SELECT ?state (MAX(?c) AS ?maxCount)
    WHERE {
      {
        SELECT ?state (COUNT(DISTINCT ?pub) AS ?c)
        WHERE {
          ?pub a coress-ont:Publication .
          ?pub coress-ont:submittedBy ?author .
          ?author coress-ont:isPerformedBy ?agent .
          ?agent coress-ont:worksInDepartment ?dept .
          ?dept coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?univ .
          ?univ coress-ont:atState ?state .
        }
        GROUP BY ?state
      }
    }
    GROUP BY ?state
  }
  FILTER(?count = ?maxCount)
}
ORDER BY ?state ?count DESC

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?pub WHERE {
  ?pub coress-ont:submittedBy ?author .
  ?author coress-ont:isPerformedBy ?agent .
  ?agent coress-ont:worksInDepartment ?dept .
} GROUP BY ?pub HAVING (COUNT(DISTINCT ?dept) > 1)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?author ?firstName ?familyName ?advisor ?fieldOfStudy
WHERE {
  ?author a coress-ont:Author .
  ?author coress-ont:advisedBy ?advisor .
  ?author coress-ont:submits ?publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
  OPTIONAL { ?author coress-ont:hasFirstName ?firstName }
  OPTIONAL { ?author coress-ont:hasFamilyName ?familyName }
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?department (COUNT(?agent) AS ?missingFamilyNameCount)
WHERE {
  ?department rdf:type coress-ont:Department .
  ?department coress-ont:hasAgent ?agent .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?name }
}
GROUP BY ?department
ORDER BY DESC(?missingFamilyNameCount)

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?author
WHERE {
  ?author rdf:type coress-ont:Author .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?doi
WHERE {
  ?publication coress-ont:hasDOI ?doi .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?dept WHERE {
  ?dept rdf:type coress-ont:Department .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?university ?city
WHERE {
  ?university a coress-ont:University .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?publication ?type
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:hasPublicationType ?type .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>
SELECT ?publication ?fieldOfStudy
WHERE {
  ?publication a coress-ont:Publication .
  ?publication coress-ont:associatedFieldOfStudy ?fieldOfStudy .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?city ?college
WHERE {
  ?college coress-ont:collegeOf ?university .
  ?university coress-ont:atCity ?city .
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?state ?university ?publicationCount
WHERE {
  {
    SELECT ?state ?university (COUNT(?pub) AS ?publicationCount)
    WHERE {
      ?pub coress-ont:submittedBy ?author .
      ?author coress-ont:worksInDepartment ?dept .
      ?dept coress-ont:departmentOf ?college .
      ?college coress-ont:collegeOf ?university .
      ?university coress-ont:atState ?state .
    }
    GROUP BY ?state ?university
  }
  {
    SELECT ?state (MAX(?cnt) AS ?maxCount)
    WHERE {
      {
        SELECT ?state ?university (COUNT(?pub) AS ?cnt)
        WHERE {
          ?pub coress-ont:submittedBy ?author .
          ?author coress-ont:worksInDepartment ?dept .
          ?dept coress-ont:departmentOf ?college .
          ?college coress-ont:collegeOf ?university .
          ?university coress-ont:atState ?state .
        }
        GROUP BY ?state ?university
      }
    }
    GROUP BY ?state
  }
  FILTER (?publicationCount = ?maxCount)
}

PREFIX coress-ont: <http://example.org/core_scholar_shallow/>

SELECT ?dept (COUNT(?agent) AS ?missingCount)
WHERE {
  ?agent a coress-ont:Agent .
  ?agent coress-ont:worksInDepartment ?dept .
  FILTER NOT EXISTS { ?agent coress-ont:hasFamilyName ?fname }
}
GROUP BY ?dept
ORDER BY DESC(?missingCount)
LIMIT 1

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?name ?startDate ?endDate ?typeLabel ?area ?cropDamage ?infraDamage ?deaths
WHERE {
  ?hazard rdf:type ?class .
  ?class rdfs:subClassOf* kwgl-ont:HazardEvent .

  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?typeLabel }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?diabeticPercent ?obesePercent ?povertyPercent
WHERE {
  ?place rdf:type kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabeticPercent }
  OPTIONAL { ?place kwgl-ont:percentObese ?obesePercent }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyPercent }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasName ?name .
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazardName ?totalCount
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType kwglr:earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?hazardName }
  {
    SELECT (COUNT(?h) AS ?totalCount)
    WHERE {
      ?h rdf:type kwgl-ont:HazardEvent .
      ?h kwgl-ont:hasHazardType kwglr:earthquake .
    }
  }
}

PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?attribute (COUNT(?all) AS ?totalCount)
WHERE {
  { SELECT (COUNT(DISTINCT ?p) AS ?all)
    WHERE {
      ?p rdf:type owl:DatatypeProperty .
      FILTER(CONTAINS(STR(?p), "Tornado"))
      FILTER(CONTAINS(STR(?p), "Place"))
    }
  }
  ?attribute rdf:type owl:DatatypeProperty .
  FILTER(CONTAINS(STR(?attribute), "Tornado"))
  FILTER(CONTAINS(STR(?attribute), "Place"))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?place ?placeName ?hurricaneDamage ?hurricaneCount ?stormSurgeDamage ?stormSurgeCount ?event ?eventType ?startDate ?endDate ?affectedArea
WHERE {
  ?place rdf:type kwgl-ont:Place .

  # Retrieve Place Name
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Retrieve specific storm-related attributes defined on Place (Hurricanes & Storm Surges)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?stormSurgeDamage }
  OPTIONAL { ?place kwgl-ont:numberOfStormSurgesImpactingPlace ?stormSurgeCount }

  # Retrieve linked HazardEvents that are storm-specific types to get event-level details
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?event .
    ?event rdf:type kwgl-ont:HazardEvent .
    ?event kwgl-ont:hasHazardType ?eventType .

    # Filter for storm-related hazard types found in the schema
    FILTER (?eventType IN (kwglr:hurricane, kwglr:tropicalStorm, kwglr:stormSurgeTide, kwglr:winterStorm, kwglr:thunderstormWind))

    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }
    OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT DISTINCT ?place ?placeName ?floodDamageTotal ?floodCountTotal ?hazardEvent ?eventStartDate ?eventEndDate ?eventCropsDamage ?eventInfraDamage
WHERE {
  ?place rdf:type kwgl-ont:Place .
  ?place kwgl-ont:hasName ?placeName .

  # Retrieve flood-specific attributes directly on the Place
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?floodDamageTotal }
  OPTIONAL { ?place kwgl-ont:numberOfFloodsImpactingPlace ?floodCountTotal }

  # Retrieve linked HazardEvents that are specifically Flood types
  OPTIONAL {
    ?place kwgl-ont:impactedBy ?hazardEvent .
    ?hazardEvent rdf:type kwgl-ont:HazardEvent .
    ?hazardEvent kwgl-ont:hasHazardType ?floodType .
    FILTER (?floodType IN (kwglr:flood, kwglr:flashFlood, kwglr:coastalFlood, kwglr:lakeshoreFlood))

    # Retrieve event-level details
    OPTIONAL { ?hazardEvent kwgl-ont:hasStartDate ?eventStartDate }
    OPTIONAL { ?hazardEvent kwgl-ont:hasEndDate ?eventEndDate }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToCropsInDollars ?eventCropsDamage }
    OPTIONAL { ?hazardEvent kwgl-ont:damageToInfrastructureInDollars ?eventInfraDamage }
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hazard ?name ?startDate ?endDate ?damageCrops ?damageInfra ?deaths ?area ?type
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasHazardType kwglr:earthquake .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfra }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
  BIND(kwglr:earthquake AS ?type)
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?event ?area ?cropsDamage ?infraDamage ?deaths
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?area }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropsDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?hazard ?cropsDamage ?infraDamage
WHERE {
  ?hazard rdf:type kwgl-ont:HazardEvent .
  ?hazard kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropsDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  FILTER (BOUND(?cropsDamage) || BOUND(?infraDamage))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?hurricaneEvent ?eventName ?startDate ?endDate ?affectedAreaInAcres ?damageToCropsInDollars ?damageToInfrastructureInDollars ?numberOfDeaths ?place ?placeName ?totalHurricaneDamage ?hurricaneDamage2018 ?hurricaneDamage2019 ?hurricaneDamage2020 ?hurricaneDamage2021 ?hurricaneDamage2022
WHERE {
  ?hurricaneEvent rdf:type kwgl-ont:Hurricane .

  OPTIONAL { ?hurricaneEvent kwgl-ont:hasName ?eventName }
  OPTIONAL { ?hurricaneEvent kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hurricaneEvent kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hurricaneEvent kwgl-ont:affectedAreaInAcres ?affectedAreaInAcres }
  OPTIONAL { ?hurricaneEvent kwgl-ont:damageToCropsInDollars ?damageToCropsInDollars }
  OPTIONAL { ?hurricaneEvent kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructureInDollars }
  OPTIONAL { ?hurricaneEvent kwgl-ont:numberOfDeaths ?numberOfDeaths }

  ?hurricaneEvent kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?totalHurricaneDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?hurricaneDamage2018 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?hurricaneDamage2019 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?hurricaneDamage2020 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?hurricaneDamage2021 }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?hurricaneDamage2022 }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?placeName ?startDate ?endDate ?cropDamage ?infraDamage ?affectedArea ?tornadoPlaceDamage
WHERE {
  ?event rdf:type kwgl-ont:Tornado .
  ?event kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .

  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate }

  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoPlaceDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?hazardType ?startDate ?endDate ?cropDamage ?infraDamage ?affectedArea
WHERE {
  ?event rdf:type kwgl-ont:HazardEvent .
  ?event kwgl-ont:hasImpacted ?place .
  ?place kwgl-ont:hasName ?placeName .
  ?event kwgl-ont:hasHazardType ?hazardType .

  # Filter for storm-specific hazards based on schema values
  VALUES ?stormTypes { 
    kwglr:hurricane 
    kwglr:tropicalStorm 
    kwglr:winterStorm 
    kwglr:blizzard 
    kwglr:dustStorm 
    kwglr:iceStorm 
    kwglr:thunderstormWind
  }
  FILTER (?hazardType IN ?stormTypes)

  # Temporal extent details
  OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
  OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }

  # Damage details available on HazardEvent
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage . }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infraDamage . }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea . }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?hazard ?name ?type ?startDate ?endDate ?deaths ?infraDamage ?cropDamage ?area
WHERE {
  ?hazard a kwgl-ont:HazardEvent .
  OPTIONAL { ?hazard kwgl-ont:hasName ?name }
  OPTIONAL { ?hazard kwgl-ont:hasHazardType ?type }
  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?infraDamage }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?area }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name
WHERE {
  ?place a kwgl-ont:Place .
  ?place kwgl-ont:hasName ?name .
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?name ?population ?households ?diabetic ?obese ?povertyLine
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?place ?name ?population ?households ?povertyLine ?diabetic ?obese
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?name }
  OPTIONAL { ?place kwgl-ont:hasPopulation ?population }
  OPTIONAL { ?place kwgl-ont:hasNumberOfHouseHolds ?households }
  OPTIONAL { ?place kwgl-ont:percentBelowPovertyLine ?povertyLine }
  OPTIONAL { ?place kwgl-ont:percentDiabetic ?diabetic }
  OPTIONAL { ?place kwgl-ont:percentObese ?obese }
  FILTER (BOUND(?population) || BOUND(?households) || BOUND(?povertyLine) || BOUND(?diabetic) || BOUND(?obese))
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?earthquakeType (COUNT(DISTINCT ?place) AS ?numberOfPlacesWithEarthquakes)
WHERE {
  ?earthquakeType a kwgl-ont:HazardType .
  FILTER(?earthquakeType = kwglr:earthquake)

  OPTIONAL {
    ?place kwgl-ont:numberOfEarthquakesImpactingPlace ?value .
  }
}
GROUP BY ?earthquakeType

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
