PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place ?placeName 
       ?avgTempJan ?avgTempFeb ?avgTempMar ?avgTempApr ?avgTempMay ?avgTempJun
       ?avgTempJul ?avgTempAug ?avgTempSep ?avgTempOct ?avgTempNov ?avgTempDec
       ?maxTempJan ?maxTempFeb ?maxTempMar ?maxTempApr ?maxTempMay ?maxTempJun
       ?maxTempJul ?maxTempAug ?maxTempSep ?maxTempOct ?maxTempNov ?maxTempDec
       ?minTempJan ?minTempFeb ?minTempMar ?minTempApr ?minTempMay ?minTempJun
       ?minTempJul ?minTempAug ?minTempSep ?minTempOct ?minTempNov ?minTempDec
       ?avgHeatDays ?avgCoolDays
       ?heatDaysJan ?heatDaysFeb ?heatDaysMar ?heatDaysApr ?heatDaysMay ?heatDaysJun
       ?heatDaysJul ?heatDaysAug ?heatDaysSep ?heatDaysOct ?heatDaysNov ?heatDaysDec
       ?coolDaysJan ?coolDaysFeb ?coolDaysMar ?coolDaysApr ?coolDaysMay ?coolDaysJun
       ?coolDaysJul ?coolDaysAug ?coolDaysSep ?coolDaysOct ?coolDaysNov ?coolDaysDec
WHERE {
  ?place a kwgl-ont:Place .
  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  # Average Monthly Temperature
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusJan2021 ?avgTempJan }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusFeb2021 ?avgTempFeb }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusMar2021 ?avgTempMar }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusApr2021 ?avgTempApr }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusMay2021 ?avgTempMay }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusJun2021 ?avgTempJun }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusJul2021 ?avgTempJul }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusAug2021 ?avgTempAug }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusSep2021 ?avgTempSep }
  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusOct2021 ?avgTempOct }
