  OPTIONAL { ?place kwgl-ont:averageMonthlyTemperatureInCelsiusDec2021 ?avgTempDec }

  # Maximum Monthly Temperature
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusJan2021 ?maxTempJan }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusFeb2021 ?maxTempFeb }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusMar2021 ?maxTempMar }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusApr2021 ?maxTempApr }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusMay2021 ?maxTempMay }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusJun2021 ?maxTempJun }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusJul2021 ?maxTempJul }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusAug2021 ?maxTempAug }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusSep2021 ?maxTempSep }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusOct2021 ?maxTempOct }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusNov2021 ?maxTempNov }
  OPTIONAL { ?place kwgl-ont:maximumMonthlyTemperatureInCelsiusDec2021 ?maxTempDec }

  # Minimum Monthly Temperature
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusJan2021 ?minTempJan }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusFeb2021 ?minTempFeb }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusMar2021 ?minTempMar }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusApr2021 ?minTempApr }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusMay2021 ?minTempMay }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusJun2021 ?minTempJun }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusJul2021 ?minTempJul }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusAug2021 ?minTempAug }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusSep2021 ?minTempSep }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusOct2021 ?minTempOct }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusNov2021 ?minTempNov }
  OPTIONAL { ?place kwgl-ont:minimumMonthlyTemperatureInCelsiusDec2021 ?minTempDec }

  # Average Heating Degree Days
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonth ?avgHeatDays }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthJan2021 ?heatDaysJan }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthFeb2021 ?heatDaysFeb }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthMar2021 ?heatDaysMar }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthApr2021 ?heatDaysApr }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthMay2021 ?heatDaysMay }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthJun2021 ?heatDaysJun }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthJul2021 ?heatDaysJul }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthAug2021 ?heatDaysAug }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthSep2021 ?heatDaysSep }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthOct2021 ?heatDaysOct }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthNov2021 ?heatDaysNov }
  OPTIONAL { ?place kwgl-ont:averageHeatingDegreeDaysPerMonthDec2021 ?heatDaysDec }

  # Average Cooling Degree Days
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonth ?avgCoolDays }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthJan2021 ?coolDaysJan }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthFeb2021 ?coolDaysFeb }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthMar2021 ?coolDaysMar }
