  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthJul2021 ?coolDaysJul }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthAug2021 ?coolDaysAug }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthSep2021 ?coolDaysSep }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthOct2021 ?coolDaysOct }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthNov2021 ?coolDaysNov }
  OPTIONAL { ?place kwgl-ont:averageCoolingDegreeDaysPerMonthDec2021 ?coolDaysDec }
