PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?earthquake ?name ?startDate ?endDate ?hazardType ?deaths ?infrastructureDamage ?cropDamage ?affectedArea
WHERE {
  ?earthquake a kwgl-ont:Earthquake .
  OPTIONAL { ?earthquake kwgl-ont:hasName ?name }
  OPTIONAL { ?earthquake kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?earthquake kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?earthquake kwgl-ont:hasHazardType ?hazardType }
  OPTIONAL { ?earthquake kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?earthquake kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage }
  OPTIONAL { ?earthquake kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?earthquake kwgl-ont:affectedAreaInAcres ?affectedArea }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?event ?deaths ?infrastructureDamage ?cropDamage ?affectedArea
WHERE {
  ?event a kwgl-ont:HazardEvent .
  OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage }
  OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage }
  OPTIONAL { ?event kwgl-ont:affectedAreaInAcres ?affectedArea }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>

SELECT ?place ?hazard 
       ?damageInfrastructure ?damageCrops ?affectedArea ?numberOfDeaths
       ?dollarDamageFires ?dollarDamageFloods ?dollarDamageHurricanes 
       ?dollarDamageLandslides ?dollarDamageStormSurges ?dollarDamageTornadoes
WHERE {
  ?place a kwgl-ont:Place .
  ?hazard a kwgl-ont:HazardEvent .
  ?place kwgl-ont:impactedBy ?hazard .

  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageInfrastructure }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageCrops }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:numberOfDeaths ?numberOfDeaths }

  OPTIONAL { ?place kwgl-ont:dollarDamageOfFiresImpactingPlace ?dollarDamageFires }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfFloodsImpactingPlace ?dollarDamageFloods }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?dollarDamageHurricanes }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfLandslidesImpactingPlace ?dollarDamageLandslides }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfStormSurgesImpactingPlace ?dollarDamageStormSurges }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?dollarDamageTornadoes }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX kwglr: <http://stko-kwg.geog.ucsb.edu/lod/lite-resource/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?place 
       ?hurricaneCount ?hurricaneDamage 
       ?count2018 ?damage2018 ?count2019 ?damage2019 ?count2020 ?damage2020 ?count2021 ?damage2021 ?count2022 ?damage2022
       ?startDate ?endDate 
       ?infrastructureDamage ?cropDamage ?deaths
WHERE {
  ?place a kwgl-ont:Place .

  # Hurricane-specific hazard attributes on Place (General)
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace ?hurricaneCount . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage . }

  # Hurricane-specific hazard attributes on Place (Yearly Temporal Data)
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?count2018 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?damage2018 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?count2019 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?damage2019 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?count2020 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?damage2020 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?count2021 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?damage2021 . }
  OPTIONAL { ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?count2022 . }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?damage2022 . }

  # Link to Hurricane Event for Temporal Data and General Damage Impact Details
  OPTIONAL { 
    ?place kwgl-ont:impactedBy ?event .
    ?event a kwgl-ont:Hurricane .

    # Temporal Data (Event Level)
    OPTIONAL { ?event kwgl-ont:hasStartDate ?startDate . }
    OPTIONAL { ?event kwgl-ont:hasEndDate ?endDate . }

    # Damage Impact Details (Event Level)
    OPTIONAL { ?event kwgl-ont:damageToInfrastructureInDollars ?infrastructureDamage . }
    OPTIONAL { ?event kwgl-ont:damageToCropsInDollars ?cropDamage . }
    OPTIONAL { ?event kwgl-ont:numberOfDeaths ?deaths . }
  }

  # Filter to ensure at least some hurricane data exists for the place
  FILTER EXISTS { 
    ?place kwgl-ont:numberOfHurricanesImpactingPlace ?_c1 . 
    UNION 
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?_d1 . 
    UNION 
    ?place kwgl-ont:numberOfHurricanesImpactingPlace2018 ?_c2 .
    UNION 
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2018 ?_d2 .
    UNION 
    ?place kwgl-ont:numberOfHurricanesImpactingPlace2019 ?_c3 .
    UNION 
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2019 ?_d3 .
    UNION 
    ?place kwgl-ont:numberOfHurricanesImpactingPlace2020 ?_c4 .
    UNION 
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2020 ?_d4 .
    UNION 
    ?place kwgl-ont:numberOfHurricanesImpactingPlace2021 ?_c5 .
    UNION 
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2021 ?_d5 .
    UNION 
    ?place kwgl-ont:numberOfHurricanesImpactingPlace2022 ?_c6 .
    UNION 
    ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace2022 ?_d6 .
  }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
SELECT ?tornado ?place ?startDate ?endDate ?eventInfraDamage ?eventCropDamage ?deaths ?affectedArea ?placeTornadoDollarDamage
WHERE {
  ?tornado a kwgl-ont:Tornado .
  ?tornado kwgl-ont:hasImpacted ?place .
  OPTIONAL { ?tornado kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?tornado kwgl-ont:hasEndDate ?endDate }
  OPTIONAL { ?tornado kwgl-ont:damageToInfrastructureInDollars ?eventInfraDamage }
  OPTIONAL { ?tornado kwgl-ont:damageToCropsInDollars ?eventCropDamage }
  OPTIONAL { ?tornado kwgl-ont:numberOfDeaths ?deaths }
  OPTIONAL { ?tornado kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?placeTornadoDollarDamage }
}

PREFIX kwgl-ont: <http://stko-kwg.geog.ucsb.edu/lod/lite-ontology/>
PREFIX owl: <http://www.w3.org/2002/07/owl#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?placeName ?hazardType ?startDate ?endDate ?damageToInfrastructure ?affectedArea ?damageToCrops ?hurricaneDamage ?tornadoDamage
WHERE {
  {
    ?hazard a kwgl-ont:Hurricane .
    BIND("Hurricane" AS ?hazardType)
  } UNION {
    ?hazard a kwgl-ont:Tornado .
    BIND("Tornado" AS ?hazardType)
  }

  ?hazard kwgl-ont:hasImpacted ?place .

  OPTIONAL { ?place kwgl-ont:hasName ?placeName }

  OPTIONAL { ?hazard kwgl-ont:hasStartDate ?startDate }
  OPTIONAL { ?hazard kwgl-ont:hasEndDate ?endDate }

  # Damage details on HazardEvent
  OPTIONAL { ?hazard kwgl-ont:damageToInfrastructureInDollars ?damageToInfrastructure }
  OPTIONAL { ?hazard kwgl-ont:affectedAreaInAcres ?affectedArea }
  OPTIONAL { ?hazard kwgl-ont:damageToCropsInDollars ?damageToCrops }

  # Damage details on Place (Aggregated by hazard type)
  OPTIONAL { ?place kwgl-ont:dollarDamageOfHurricanesImpactingPlace ?hurricaneDamage }
  OPTIONAL { ?place kwgl-ont:dollarDamageOfTornadoesImpactingPlace ?tornadoDamage }
}
